@Test
@Ignore
public void testStreamLoad() throws Exception {
    DorisOptions options = DorisOptions.builder().withFenodes("127.0.0.1:8030").withDatabase("test").withTable("test_flink_c").withUsername("root").withPassword("").withBufferFlushMaxBytes(10240000000L).withBufferFlushMaxRows(100000).withStreamLoadProp(new Properties()).build();
    DorisBatchStreamLoad streamLoad = new DorisBatchStreamLoad(options, new LogChannel());
    streamLoad.writeRecord(options.getDatabase(), options.getTable(), "zhangsan\t10".getBytes(StandardCharsets.UTF_8));
    while (!streamLoad.isLoadThreadAlive()) {
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
        }
    }
    streamLoad.forceFlush();
    // stay main thread alive
    Thread.sleep(10000);
}

@Test
public void testSerialize() throws Exception {
    ValueMetaInterface[] formatMeta = new ValueMetaInterface[] { new ValueMetaBoolean("boolean"), new ValueMetaInteger("integer"), new ValueMetaNumber("number"), new ValueMetaBigNumber("bignumber"), new ValueMetaDate("date"), new ValueMetaTimestamp("timestamp"), new ValueMetaBinary("binary"), new ValueMetaString("string"), new ValueMetaInternetAddress("address") };
    DorisRecordSerializer serializer = DorisRecordSerializer.builder().setType(CSV).setFieldNames(new String[] { "c_boolean", "c_integer", "c_number", "c_bignumber", "c_date", "c_timestamp", "c_binary", "c_string", "c_internetAddress" }).setFormatMeta(formatMeta).setFieldDelimiter(",").setLogChannelInterface(new LogChannel()).setDeletable(false).build();
    SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");
    Object[] data = new Object[] { true, 10L, 123.23, new BigDecimal("123456789.1234"), dateFormat.parse("2024-01-01"), Timestamp.valueOf("2024-01-01 10:11:22.123"), "binary", "string", new InternetAddress("127.0.0.1") };
    String actual = serializer.buildCSVString(data, formatMeta.length);
    String except = "true,10,123.23,123456789.1234,2024-01-01,2024-01-01 10:11:22.123,binary,string,127.0.0.1";
    Assert.assertEquals(except, actual);
}

