    ExceptionChecker.expectThrowsWithMsg(DdlException.class, "Provide start or history_partition_num property when create_history_partition=true. " + "Otherwise set create_history_partition=false", () -> createTable(createOlapTblStmt));
    String createOlapTblStmt2 = "CREATE TABLE test.`dynamic_partition3` (
