@Test
public void testDoesNotModifyExistingColumns() throws Exception {
    // Create a mock audit table with storage-related columns but with inconsistent types (VARCHAR instead of BIGINT)
    List<Column> initialSchema = Lists.newArrayList(new Column("query_id", ScalarType.createVarcharType(48), true, null, false, null, ""), new Column("time", ScalarType.createDatetimeV2Type(3), true, null, false, null, ""), new Column("client_ip", ScalarType.createVarcharType(128), true, null, false, null, ""), new Column("user", ScalarType.createVarcharType(128), true, null, false, null, ""), new Column("catalog", ScalarType.createVarcharType(128), true, null, false, null, ""), new Column("db", ScalarType.createVarcharType(128), true, null, false, null, ""), new Column("state", ScalarType.createVarcharType(128), true, null, false, null, ""), new Column("error_code", ScalarType.INT, true, null, false, null, ""), new Column("error_message", ScalarType.STRING, true, null, false, null, ""), new Column("query_time", ScalarType.BIGINT, true, null, false, null, ""), new Column("scan_bytes", ScalarType.BIGINT, true, null, false, null, ""), new Column("scan_rows", ScalarType.BIGINT, true, null, false, null, ""), new Column("return_rows", ScalarType.BIGINT, true, null, false, null, ""), new Column("shuffle_send_rows", ScalarType.BIGINT, true, null, false, null, ""), new Column("shuffle_send_bytes", ScalarType.BIGINT, true, null, false, null, ""), // Intentionally use inconsistent types (VARCHAR instead of BIGINT)
    new Column("scan_bytes_from_local_storage", ScalarType.createVarcharType(128), true, null, false, null, ""), new Column("scan_bytes_from_remote_storage", ScalarType.createVarcharType(128), true, null, false, null, ""));
    // Use the correct constructor to create OlapTable to ensure nameToColumn is properly initialized
    OlapTable auditTable = new OlapTable(1000, "audit_log", initialSchema, KeysType.AGG_KEYS, new SinglePartitionInfo(), new HashDistributionInfo());
    // Verify columns exist and have VARCHAR type
    Column localStorageCol = auditTable.getColumn("scan_bytes_from_local_storage");
    Column remoteStorageCol = auditTable.getColumn("scan_bytes_from_remote_storage");
    Assertions.assertNotNull(localStorageCol, "The scan_bytes_from_local_storage column should exist in auditTable");
    Assertions.assertNotNull(remoteStorageCol, "The scan_bytes_from_remote_storage column should exist in auditTable");
    Assertions.assertTrue(localStorageCol.getType().isVarchar(), "The scan_bytes_from_local_storage column type should be VARCHAR");
    Assertions.assertTrue(remoteStorageCol.getType().isVarchar(), "The scan_bytes_from_remote_storage column type should be VARCHAR");
    // Get complete column definitions from InternalSchema.AUDIT_SCHEMA
    List<ColumnDef> expectedSchema = Lists.newArrayList();
    for (ColumnDef def : InternalSchema.AUDIT_SCHEMA) {
        expectedSchema.add(def);
    }
    // Simulate column processing logic in InternalSchemaInitializer
    List<AlterClause> alterClauses = Lists.newArrayList();
    // Add columns if they don't exist
    for (int i = 0; i < expectedSchema.size(); i++) {
        ColumnDef def = expectedSchema.get(i);
        if (auditTable.getColumn(def.getName()) == null) {
            // If column doesn't exist, add it
            String afterColumn = null;
            if (i > 0) {
                for (int j = i - 1; j >= 0; j--) {
                    String prevColName = expectedSchema.get(j).getName();
                    if (auditTable.getColumn(prevColName) != null) {
                        afterColumn = prevColName;
                        break;
                    }
                }
            }
            ColumnPosition position = afterColumn == null ? ColumnPosition.FIRST : new ColumnPosition(afterColumn);
            ModifyColumnClause clause = new ModifyColumnClause(def, position, null, Maps.newHashMap());
            clause.setColumn(def.toColumn());
            alterClauses.add(clause);
        }
        // Note: InternalSchemaInitializer.created() method does not check if column types match
        // It only adds columns that don't exist in the table
    }
    // Check if AlterClauses were generated for storage-related columns
    boolean hasLocalStorageClause = false;
    boolean hasRemoteStorageClause = false;
    for (AlterClause clause : alterClauses) {
        ModifyColumnClause modifyClause = (ModifyColumnClause) clause;
        if (modifyClause.getColumn().getName().equals("scan_bytes_from_local_storage")) {
            hasLocalStorageClause = true;
        } else if (modifyClause.getColumn().getName().equals("scan_bytes_from_remote_storage")) {
            hasRemoteStorageClause = true;
        }
    }
    // Verify the system does not generate AlterClauses for columns that already exist
    // even if their types don't match the expected types
    Assertions.assertFalse(hasLocalStorageClause, "The system should not generate AlterClause for the scan_bytes_from_local_storage column that already exists");
    Assertions.assertFalse(hasRemoteStorageClause, "The system should not generate AlterClause for the scan_bytes_from_remote_storage column that already exists");
}

