    // external mysql db
    ExternalMysqlDatabase mysqlDb = (ExternalMysqlDatabase) test1.getDbNullable(MysqlDb.DATABASE_NAME);
    Assertions.assertNotNull(mysqlDb);
    for (String tblName : MysqlDBTable.TABLE_MAP.keySet()) {
