@Test
public void testStructWithNestedFieldsExactMatch() {
    // struct<f1:int, f2:array<int>>
    StructType s1 = new StructType(new StructField("f1", Type.INT, null, true), new StructField("f2", new ArrayType(Type.INT, true), null, true));
    StructType s2 = new StructType(new StructField("x", Type.INT, null, true), new StructField("y", new ArrayType(Type.INT, true), null, true));
    // names are ignored by matchExactType recursion; matchesType requires containsNull equal
    Assert.assertTrue(Type.matchExactType(s1, s2));
    // inner element type differs
    StructType s3 = new StructType(new StructField("f1", Type.INT, null, true), new StructField("f2", new ArrayType(Type.BIGINT, true), null, true));
    Assert.assertFalse(Type.matchExactType(s1, s3));
    // field nullability differs -> matchesType fails upfront
    StructType s4 = new StructType(new StructField("f1", Type.INT, null, false), new StructField("f2", new ArrayType(Type.INT, true), null, true));
    Assert.assertFalse(Type.matchExactType(s1, s4));
}

