@Test
public void testRelocateAndBalance() throws Exception {
    Env env = Env.getCurrentEnv();
    String createDbStmtStr = "create database test;";
    NereidsParser nereidsParser = new NereidsParser();
    LogicalPlan logicalPlan = nereidsParser.parseSingle(createDbStmtStr);
    StmtExecutor stmtExecutor = new StmtExecutor(connectContext, createDbStmtStr);
    if (logicalPlan instanceof CreateDatabaseCommand) {
        ((CreateDatabaseCommand) logicalPlan).run(connectContext, stmtExecutor);
    }
    Random random = new Random();
    final int groupNum = 100;
    for (int groupIndex = 0; groupIndex <= groupNum; groupIndex++) {
        int tableNum = 1 + random.nextInt(10);
        for (int tableIndex = 0; tableIndex < tableNum; tableIndex++) {
            String sql = String.format("CREATE TABLE test.table_%s_%s\n" + "( k1 int, k2 int, v1 int )\n" + "ENGINE=OLAP\n" + "UNIQUE KEY (k1,k2)\n" + "DISTRIBUTED BY HASH(k2) BUCKETS 11\n" + "PROPERTIES('colocate_with' = 'group_%s');", groupIndex, tableIndex, groupIndex);
            nereidsParser = new NereidsParser();
            LogicalPlan parsed = nereidsParser.parseSingle(sql);
            stmtExecutor = new StmtExecutor(connectContext, sql);
            if (parsed instanceof CreateTableCommand) {
                ((CreateTableCommand) parsed).run(connectContext, stmtExecutor);
            }
            BalanceStatistic beforeBalanceStatistic = BalanceStatistic.getCurrentBalanceStatistic();
            Assert.assertEquals("group: " + groupIndex + ", table: " + tableIndex + ", " + beforeBalanceStatistic.getBackendTotalReplicaNum(), 0, beforeBalanceStatistic.getBeMinTotalReplicaNum());
        }
    }
    ColocateTableIndex colocateIndex = env.getColocateTableIndex();
    Set<GroupId> groupIds = colocateIndex.getAllGroupIds();
    RebalancerTestUtil.updateReplicaDataSize(1L << 10, 10, 10);
    RebalancerTestUtil.updateReplicaPathHash();
    BalanceStatistic beforeBalanceStatistic = BalanceStatistic.getCurrentBalanceStatistic();
    Assert.assertEquals("" + beforeBalanceStatistic.getBackendTotalReplicaNum(), 0, beforeBalanceStatistic.getBeMinTotalReplicaNum());
    // all groups stable
    Thread.sleep(1000);
    Assert.assertTrue("some groups are unstable", groupIds.stream().noneMatch(groupId -> colocateIndex.isGroupUnstable(groupId)));
    // after enable colocate balance and some backends return,  it should relocate all groups.
    // and they will be unstable
    Map<String, String> tagMap = backends.get(TEMP_DISALBE_BE_NUM).getTagMap();
    for (int i = 0; i < TEMP_DISALBE_BE_NUM; i++) {
        backends.get(i).setTagMap(tagMap);
    }
    Config.disable_colocate_balance = false;
    for (int i = 0; i < 10; i++) {
        Thread.sleep(1000);
        if (groupIds.stream().allMatch(groupId -> colocateIndex.isGroupUnstable(groupId))) {
            break;
        }
    }
    Assert.assertTrue("some groups are stable", groupIds.stream().allMatch(groupId -> colocateIndex.isGroupUnstable(groupId)));
    // after enable scheduler, the unstable groups should shed their tablets and change to stable
    Config.disable_tablet_scheduler = false;
    for (int i = 0; true; i++) {
        Thread.sleep(1000);
        boolean allStable = groupIds.stream().noneMatch(groupId -> colocateIndex.isGroupUnstable(groupId));
        if (allStable) {
            break;
        }
        Assert.assertTrue("some groups are unstable", i < 60);
    }
    System.out.println("=== before colocate relocate and balance:");
    beforeBalanceStatistic.printToStdout();
    Assert.assertEquals("" + beforeBalanceStatistic.getBackendTotalReplicaNum(), 0, beforeBalanceStatistic.getBeMinTotalReplicaNum());
    Assert.assertEquals("" + beforeBalanceStatistic.getBackendTotalDataSize(), 0, beforeBalanceStatistic.getBeMinTotalDataSize());
    long beforeDataSizeDiff = beforeBalanceStatistic.getBeMaxTotalDataSize() - beforeBalanceStatistic.getBeMinTotalDataSize();
    int beforeReplicaNumDiff = beforeBalanceStatistic.getBeMaxTotalReplicaNum() - beforeBalanceStatistic.getBeMinTotalReplicaNum();
    BalanceStatistic afterBalanceStatistic = BalanceStatistic.getCurrentBalanceStatistic();
    System.out.println("");
    System.out.println("=== after colocate relocate and balance:");
    afterBalanceStatistic.printToStdout();
    Assert.assertTrue("" + afterBalanceStatistic.getBackendTotalReplicaNum(), afterBalanceStatistic.getBeMinTotalReplicaNum() > 0);
    Assert.assertTrue("" + afterBalanceStatistic.getBackendTotalDataSize(), afterBalanceStatistic.getBeMinTotalDataSize() > 0);
    long afterDataSizeDiff = afterBalanceStatistic.getBeMaxTotalDataSize() - afterBalanceStatistic.getBeMinTotalDataSize();
    int afterReplicaNumDiff = afterBalanceStatistic.getBeMaxTotalReplicaNum() - afterBalanceStatistic.getBeMinTotalReplicaNum();
    Assert.assertTrue(afterDataSizeDiff <= beforeDataSizeDiff);
    Assert.assertTrue(afterReplicaNumDiff <= beforeReplicaNumDiff);
}

