        Assert.assertTrue(rebalancer.hasPrioBackends());
    }
    // CHECKSTYLE IGNORE THIS LINE
    // remove
    for (int i = 0; i < 3; i++) {
        List<Backend> backends = Lists.newArrayList(RebalancerTestUtil.createBackend(10086 + i, 2048, 0));
        rebalancer.removePrioBackends(backends);
