@Test
void testDbName() {
    boolean defaultUnicode = VariableMgr.getDefaultSessionVariable().enableUnicodeNameSupport;
    boolean defaultNestedNamespace = GlobalVariable.enableNestedNamespace;
    List<Boolean> enableUnicode = Lists.newArrayList(false, true);
    List<Boolean> enableNestedNamespace = Lists.newArrayList(false, true);
    // Names that are always valid regardless of nested namespace setting
    List<String> alwaysValid = Arrays.asList(// ASCII letters + numbers
    "abc123", // with allowed symbols (-_)
    "A-1_b", // single ASCII letter
    "Z", // alphanumeric
    "a1b2c3", // underscore and hyphen
    "x_y-z", // letters only
    "test", // multiple hyphens
    "a-b-c", // underscore
    "a_b", // hyphen + number
    "a-1", // uppercase + number
    "B2");
    // Names that are always invalid regardless of settings
    List<String> alwaysInvalid = Arrays.asList(// starts with number
    "1abc", // contains invalid symbol @
    "@test", // empty string
    "", // contains space
    "a b", // contains invalid symbol !
    "abc!", // contains newline
    "a\nb", // contains invalid symbol $
    "abc$", // starts with hyphen
    "-abc", // starts with underscore
    "_abc", // contains asterisk
    "a*b", // contains hash symbol
    "a#b");
    // Names with dots - only valid when nested namespace is enabled
    List<String> dotNames = Arrays.asList(// database name with dot in middle
    "db1.db2", // multiple dots in middle
    "db1.db2.db3", // multiple segments with dots
    "a.b.c.d", // simple dot notation
    "test.prod", // nested database name
    "system.user.profile");
    // Names with dots that are always invalid (start/end with dot, consecutive dots)
    List<String> invalidDotNames = Arrays.asList(// starts with dot
    ".abc", // ends with dot
    "abc.", // starts with dot
    ".abc.def", // ends with dot
    "abc.def.", // consecutive dots
    "a..b", // ends with dot after valid segment
    "a.b.", // starts with dot before valid segment
    ".a.b");
    // Unicode names that are always valid
    List<String> unicodeValid = Lists.newArrayList(// French letters
    "éclair", // German umlaut
    "über", // Chinese characters
    "北京", // Japanese + numbers
    "東京123", // German umlaut
    "München", // French accent
    "Beyoncé", // Greek letters
    "αβγ", // Cyrillic letters
    "русский", // Nordic letter
    "øre", // Portuguese letter
    "ção", // French diacritic
    "naïve", // special diacritic
    "Ḥello", // German sharp S
    "ẞig");
    // Unicode names with dots - only valid when both unicode and nested namespace are enabled
    List<String> unicodeDotNames = Lists.newArrayList(// Chinese and Japanese with dot
    "北京.東京", // French words with dot
    "café.système", // German words with dot
    "über.München", // Greek and Cyrillic with dot
    "αβγ.русский");
    try {
        for (Boolean unicode : enableUnicode) {
            for (Boolean nestedNamespace : enableNestedNamespace) {
                VariableMgr.getDefaultSessionVariable().setEnableUnicodeNameSupport(unicode);
                GlobalVariable.enableNestedNamespace = nestedNamespace;
                // Test always valid names
                for (String s : alwaysValid) {
                    ExceptionChecker.expectThrowsNoException(() -> FeNameFormat.checkDbName(s));
                }
                // Test always invalid names
                for (String s : alwaysInvalid) {
                    Assertions.assertThrowsExactly(AnalysisException.class, () -> FeNameFormat.checkDbName(s), "name should be invalid: " + s + " (unicode=" + unicode + ", nested=" + nestedNamespace + ")");
                }
                // Test names with invalid dot patterns (always invalid)
                for (String s : invalidDotNames) {
                    Assertions.assertThrowsExactly(AnalysisException.class, () -> FeNameFormat.checkDbName(s), "name should be invalid: " + s + " (unicode=" + unicode + ", nested=" + nestedNamespace + ")");
                }
                // Test names with dots (valid only when nested namespace is enabled)
                for (String s : dotNames) {
                    if (nestedNamespace) {
                        ExceptionChecker.expectThrowsNoException(() -> FeNameFormat.checkDbName(s));
                    } else {
                        Assertions.assertThrowsExactly(AnalysisException.class, () -> FeNameFormat.checkDbName(s), "name should be invalid when nested namespace is disabled: " + s);
                    }
                }
                // Test unicode names
                for (String s : unicodeValid) {
                    if (unicode) {
                        ExceptionChecker.expectThrowsNoException(() -> FeNameFormat.checkDbName(s));
                    } else {
                        Assertions.assertThrowsExactly(AnalysisException.class, () -> FeNameFormat.checkDbName(s), "unicode name should be invalid when unicode issh bi     disabled: " + s);
                    }
                }
                // Test unicode names with dots (valid only when both unicode and nested namespace are enabled)
                for (String s : unicodeDotNames) {
                    if (unicode && nestedNamespace) {
                        ExceptionChecker.expectThrowsNoException(() -> FeNameFormat.checkDbName(s));
                    } else {
                        Assertions.assertThrowsExactly(AnalysisException.class, () -> FeNameFormat.checkDbName(s), "unicode dot name should be invalid: " + s + " (unicode=" + unicode + ", nested=" + nestedNamespace + ")");
                    }
                }
            }
        }
    } finally {
        VariableMgr.getDefaultSessionVariable().setEnableUnicodeNameSupport(defaultUnicode);
        GlobalVariable.enableNestedNamespace = defaultNestedNamespace;
    }
}

@Test
public void testSetMaxPerKey() throws Exception {
    TNetworkAddress address = new TNetworkAddress(ip, port);
    BackendService.Client object1;
    BackendService.Client object2;
    BackendService.Client object3;
    // first success
    object1 = backendService.borrowObject(address);
    // second success
    object2 = backendService.borrowObject(address);
    // third fail, because the max connection is 2
    boolean flag = false;
    try {
        object3 = backendService.borrowObject(address);
    } catch (java.util.NoSuchElementException e) {
        flag = true;
        // pass
    } catch (Exception e) {
        Assert.fail();
    }
    Assert.assertTrue(flag);
    // fourth success, because we drop the object1
    backendService.returnObject(address, object1);
    object3 = null;
    object3 = backendService.borrowObject(address);
    Assert.assertTrue(object3 != null);
    backendService.returnObject(address, object2);
    backendService.returnObject(address, object3);
}

