    boolean flag = false;
    try {
        object = backendService.borrowObject(null);
    } catch (NullPointerException e) {
        flag = true;
    }
    Assert.assertTrue(flag);
    flag = false;
    // return twice
    object = backendService.borrowObject(address);
    backendService.returnObject(address, object);
