    }
    cache.cleanUp();
    Assert.assertEquals(maximumSize, cache.size());
    Assert.assertEquals(maximumSize, ((EvictableCache<?, ?>) cache).tokensCount());
    // Ensure cache is effective, i.e. some entries preserved
