@Test
public void testGetByteUint() {
    Pair<Double, String> result;
    result = DebugUtil.getByteUint(0);
    Assert.assertEquals(result.first, Double.valueOf(0.0));
    Assert.assertEquals(result.second, "");
    // B
    result = DebugUtil.getByteUint(123);
    Assert.assertEquals(result.first, Double.valueOf(123.0));
    Assert.assertEquals(result.second, "B");
    // K
    result = DebugUtil.getByteUint(123456);
    Assert.assertEquals(result.first, Double.valueOf(120.5625));
    Assert.assertEquals(result.second, "KB");
    // M
    result = DebugUtil.getByteUint(1234567);
    Assert.assertEquals(result.first, Double.valueOf(1.1773748397827148));
    Assert.assertEquals(result.second, "MB");
    // G
    result = DebugUtil.getByteUint(1234567890L);
    Assert.assertEquals(result.first, Double.valueOf(1.1497809458523989));
    Assert.assertEquals(result.second, "GB");
}

@Test
public void testUtilGetStackTrace() {
    Exception e1 = new Exception("exception1");
    DdlException e2 = new DdlException("exception2", e1);
    e2.printStackTrace();
    System.out.println(Util.getRootCauseStack(e2));
    Assert.assertTrue(Util.getRootCauseStack(e2).contains("java.lang.Exception: exception1"));
    DdlException e3 = new DdlException("only one exception");
    System.out.println(Util.getRootCauseStack(e3));
    Assert.assertTrue(Util.getRootCauseStack(e3).contains("org.apache.doris.common.DdlException: errCode = 2, detailMessage = only one exception"));
    Assert.assertEquals("unknown", Util.getRootCauseStack(null));
}

@Test
public void testParseIdFromString() {
    // test null
    TUniqueId nullTUniqueId = null;
    try {
        nullTUniqueId = DebugUtil.parseTUniqueIdFromString(null);
    } catch (NumberFormatException e) {
        Assert.assertTrue("invalid query id".equals(e.getMessage()));
    }
    Assert.assertTrue(nullTUniqueId == null);
    try {
        nullTUniqueId = DebugUtil.parseTUniqueIdFromString("");
    } catch (NumberFormatException e) {
        Assert.assertTrue("invalid query id".equals(e.getMessage()));
    }
    Assert.assertTrue(nullTUniqueId == null);
    Assert.assertEquals(new TUniqueId(), DebugUtil.parseTUniqueIdFromString("0-0"));
    try {
        nullTUniqueId = DebugUtil.parseTUniqueIdFromString("INVALID-STRING");
    } catch (NumberFormatException e) {
        Assert.assertTrue(e.getMessage().contains("For input string"));
    }
    Assert.assertTrue(nullTUniqueId == null);
    for (int i = 0; i < 100; i++) {
        UUID uuid = UUID.randomUUID();
        TUniqueId originTQueryId = new TUniqueId(uuid.getMostSignificantBits(), uuid.getLeastSignificantBits());
        String originStrQueryId = DebugUtil.printId(originTQueryId);
        TUniqueId convertedTQueryId = DebugUtil.parseTUniqueIdFromString(originStrQueryId);
        String convertedStrQueryId = DebugUtil.printId(convertedTQueryId);
        Assert.assertTrue(originTQueryId.hi == convertedTQueryId.hi);
        Assert.assertTrue(originTQueryId.lo == convertedTQueryId.lo);
        Assert.assertTrue(originStrQueryId.equals(convertedStrQueryId));
    }
}

@Test
public void testGetPartitionRangeString() throws DateTimeException {
    // TimeUnit: DAY
    // 1. 2020-05-25, offset -7
    DynamicPartitionProperty property = new DynamicPartitionProperty(getDynamProp("DAY", -3, 3, -1, -1));
    String res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-05-25"), -7, FORMAT);
    Assert.assertEquals("2020-05-18", res);
    String partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "DAY");
    Assert.assertEquals("20200518", partName);
    // 2. 2020-05-25, offset 0
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-05-25"), 0, FORMAT);
    Assert.assertEquals("2020-05-25", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "DAY");
    Assert.assertEquals("20200525", partName);
    // 3. 2020-05-25, offset 7
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-05-25"), 7, FORMAT);
    Assert.assertEquals("2020-06-01", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "DAY");
    Assert.assertEquals("20200601", partName);
    // 4. 2020-02-28, offset 3
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-02-28"), 3, FORMAT);
    Assert.assertEquals("2020-03-02", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "DAY");
    Assert.assertEquals("20200302", partName);
    // TimeUnit: WEEK
    // 1. 2020-05-25, start day: MONDAY, offset 0
    property = new DynamicPartitionProperty(getDynamProp("WEEK", -3, 3, 1, -1));
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-05-25"), 0, FORMAT);
    Assert.assertEquals("2020-05-25", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "WEEK");
    Assert.assertEquals("2020_22", partName);
    // 2. 2020-05-28, start day: MONDAY, offset 0
    property = new DynamicPartitionProperty(getDynamProp("WEEK", -3, 3, 1, -1));
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-05-28"), 0, FORMAT);
    Assert.assertEquals("2020-05-25", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "WEEK");
    Assert.assertEquals("2020_22", partName);
    // 3. 2020-05-25, start day: SUNDAY, offset 0
    property = new DynamicPartitionProperty(getDynamProp("WEEK", -3, 3, 7, -1));
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-05-25"), 0, FORMAT);
    Assert.assertEquals("2020-05-31", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "WEEK");
    Assert.assertEquals("2020_23", partName);
    // 4. 2020-05-25, start day: MONDAY, offset -2
    property = new DynamicPartitionProperty(getDynamProp("WEEK", -3, 3, 1, -1));
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-05-25"), -2, FORMAT);
    Assert.assertEquals("2020-05-11", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "WEEK");
    Assert.assertEquals("2020_20", partName);
    // 5. 2020-02-29, start day: WED, offset 0
    property = new DynamicPartitionProperty(getDynamProp("WEEK", -3, 3, 3, -1));
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-02-29"), 0, FORMAT);
    Assert.assertEquals("2020-02-26", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "WEEK");
    Assert.assertEquals("2020_09", partName);
    // 6. 2020-02-29, start day: TUS, offset 1
    property = new DynamicPartitionProperty(getDynamProp("WEEK", -3, 3, 2, -1));
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-02-29"), 1, FORMAT);
    Assert.assertEquals("2020-03-03", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "WEEK");
    Assert.assertEquals("2020_10", partName);
    // 6. 2020-01-01, start day: MONDAY, offset -1
    property = new DynamicPartitionProperty(getDynamProp("WEEK", -3, 3, 1, -1));
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-01-01"), -1, FORMAT);
    Assert.assertEquals("2019-12-23", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "WEEK");
    Assert.assertEquals("2019_52", partName);
    // 6. 2020-01-01, start day: MONDAY, offset 0
    property = new DynamicPartitionProperty(getDynamProp("WEEK", -3, 3, 1, -1));
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-01-01"), 0, FORMAT);
    Assert.assertEquals("2019-12-30", res);
    partName = DynamicPartitionUtil.getFormattedPartitionName(getCTSTimeZone(), res, "WEEK");
    Assert.assertEquals("2019_53", partName);
    // TimeUnit: MONTH
    // 1. 2020-05-25, start day: 1, offset 0
    property = new DynamicPartitionProperty(getDynamProp("MONTH", -3, 3, -1, 1));
    res = DynamicPartitionUtil.getPartitionRangeString(property, getZonedDateTimeFromStr("2020-05-25"), 0, FORMAT);
