@Test
public void testHdfsLocationConvert() throws UserException {
    // non HA
    LocationPath locationPath = LocationPath.of("hdfs://dir/file.path");
    Assertions.assertTrue(locationPath.getNormalizedLocation().startsWith("hdfs://"));
    Assertions.assertEquals(locationPath.getFsIdentifier(), "hdfs://dir");
    // HA props
    Map<String, String> props = new HashMap<>();
    props.put("dfs.nameservices", "ns1");
    // NameNodes for this nameservice
    props.put("dfs.ha.namenodes.ns1", "nn1,nn2");
    // RPC addresses for each NameNode
    props.put("dfs.namenode.rpc-address.ns1.nn1", "127.0.0.1:8020");
    props.put("dfs.namenode.rpc-address.ns1.nn2", "127.0.0.2:8020");
    props.put("dfs.client.failover.proxy.provider.ns1", "org.apache.hadoop.hdfs.server.namenode.ha.ConfiguredFailoverProxyProvider");
    //HdfsProperties hdfsProperties = (HdfsProperties) StorageProperties.createPrimary( props);
    Map<StorageProperties.Type, StorageProperties> storagePropertiesMap = StorageProperties.createAll(props).stream().collect(java.util.stream.Collectors.toMap(StorageProperties::getType, Function.identity()));
    locationPath = LocationPath.of("hdfs:///dir/file.path", storagePropertiesMap);
    Assertions.assertTrue(locationPath.getNormalizedLocation().startsWith("hdfs://") && !locationPath.getNormalizedLocation().startsWith("hdfs:///"));
    // nonstandard '/' for hdfs path
    locationPath = LocationPath.of("hdfs:/dir/file.path", storagePropertiesMap);
    Assertions.assertTrue(locationPath.getNormalizedLocation().startsWith("hdfs://"));
}

