@Test
public void testVersion() {
    DigitalVersion v = new DigitalVersion(1100000);
    System.out.println(v);
    Assert.assertEquals(1, v.major);
    Assert.assertEquals(10, v.minor);
    Assert.assertEquals(0, v.revision);
    DigitalVersion s = new DigitalVersion((byte) 50, (byte) 2, (byte) 3);
    Assert.assertEquals(50020300, s.id);
    Assert.assertTrue(s.onOrAfter(v));
    Assert.assertFalse(s.before(v));
    DigitalVersion vs = new DigitalVersion((byte) 1, (byte) 10, (byte) 0);
    Assert.assertEquals(vs, v);
}

@Test
public void testFromString() {
    try {
        Assert.assertEquals(1060000, DigitalVersion.fromString("1.6.0.123.123").id);
    } catch (IllegalArgumentException e) {
        e.printStackTrace();
    }
    try {
        DigitalVersion.fromString("");
    } catch (Exception e) {
        Assert.assertTrue(e instanceof IllegalArgumentException);
        Assert.assertTrue(e.getMessage().contains("Illegal empty version"));
    }
    try {
        DigitalVersion.fromString("1.6123123.123");
    } catch (Exception e) {
        Assert.assertTrue(e instanceof IllegalArgumentException);
        Assert.assertTrue(e.getMessage().contains("Illegal version format"));
    }
    try {
        DigitalVersion.fromString("a.b.c");
    } catch (Exception e) {
        Assert.assertTrue(e instanceof IllegalArgumentException);
        Assert.assertTrue(e.getMessage().contains("Illegal version format"));
    }
}

@Test
public void updateCooldownConf() {
    List<CooldownConf> confToUpdate = new LinkedList<>();
    CooldownConf cooldownConf = new CooldownConf(dbId, tableId, partitionId, indexId, tabletId, 100);
    confToUpdate.add(cooldownConf);
    CooldownConfHandler cooldownConfHandler = new CooldownConfHandler();
    cooldownConfHandler.addCooldownConfToUpdate(confToUpdate);
    cooldownConfHandler.runAfterCatalogReady();
    Pair<Long, Long> conf = tablet.getCooldownConf();
    long cooldownReplicaId = conf.first;
    long cooldownTerm = conf.second;
    boolean matched = false;
    for (Replica replica : tablet.getReplicas()) {
        if (replica.getId() == cooldownReplicaId) {
            matched = true;
            break;
        }
    }
    Assert.assertTrue(matched);
    Assert.assertEquals(101, cooldownTerm);
}

@Test
public void testShowTableStatusPrivs() throws Exception {
    ConnectContext root = createCtx(UserIdentity.ROOT, "127.0.0.1");
    NereidsParser nereidsParser = new NereidsParser();
    String sql = "create user show_table_status identified by '123456'";
    LogicalPlan parsed = nereidsParser.parseSingle(sql);
    StmtExecutor stmtExecutor = new StmtExecutor(root, sql);
    if (parsed instanceof CreateUserCommand) {
        ((CreateUserCommand) parsed).run(root, stmtExecutor);
    }
    LogicalPlan logicalPlan1 = nereidsParser.parseSingle("grant select_priv on test2.*.* to show_table_status;");
    Assertions.assertTrue(logicalPlan1 instanceof GrantTablePrivilegeCommand);
    GrantTablePrivilegeCommand command1 = (GrantTablePrivilegeCommand) logicalPlan1;
    command1.validate();
    auth.grantTablePrivilegeCommand(command1);
    // show table status from test2.db1 LIKE "%tbl%
    UserIdentity user = UserIdentity.createAnalyzedUserIdentWithIp("show_table_status", "%");
    ConnectContext userCtx = createCtx(user, "127.0.0.1");
    ShowTableStatusCommand command = new ShowTableStatusCommand("db1", "test2", "%tbl%", null);
    ShowResultSet resultSet = command.doRun(userCtx, new StmtExecutor(userCtx, ""));
    Assert.assertEquals(2, resultSet.getResultRows().size());
}

