@Test
public void testCreateBranchWithNotEmptyTable() throws UserException, IOException {
    String branch1 = "branch1";
    String branch2 = "branch2";
    String branch3 = "branch3";
    // create a new branch: branch1
    CreateOrReplaceBranchInfo info = new CreateOrReplaceBranchInfo(branch1, true, false, false, BranchOptions.EMPTY);
    catalog.createOrReplaceBranch(dorisTable, info);
    List<Snapshot> snapshots = Lists.newArrayList(icebergTable.snapshots());
    Assertions.assertEquals(1, snapshots.size());
    assertSnapshotRef(icebergTable.refs().get(branch1), snapshots.get(0).snapshotId(), true, null, null, null);
    // create an existed branch, failed
    Assertions.assertThrowsExactly(RuntimeException.class, () -> catalog.createOrReplaceBranch(dorisTable, info));
    // create or replace an empty branch, will fail
    // because cannot perform a replace operation on an empty branch.
    CreateOrReplaceBranchInfo info2 = new CreateOrReplaceBranchInfo(branch1, true, true, false, BranchOptions.EMPTY);
    Assertions.assertThrows(UserException.class, () -> catalog.createOrReplaceBranch(dorisTable, info2));
    // create an existed branch with ifNotExists
    CreateOrReplaceBranchInfo info4 = new CreateOrReplaceBranchInfo(branch1, true, false, true, BranchOptions.EMPTY);
    catalog.createOrReplaceBranch(dorisTable, info4);
    assertSnapshotRef(icebergTable.refs().get(branch1), snapshots.get(0).snapshotId(), true, null, null, null);
    // add some data
    addSomeDataIntoIcebergTable();
    snapshots = Lists.newArrayList(icebergTable.snapshots());
    Assertions.assertEquals(2, snapshots.size());
    // update branch1
    catalog.createOrReplaceBranch(dorisTable, info2);
    assertSnapshotRef(icebergTable.refs().get(branch1), icebergTable.currentSnapshot().snapshotId(), true, null, null, null);
    // create or replace a new branch: branch2
    CreateOrReplaceBranchInfo info3 = new CreateOrReplaceBranchInfo(branch2, true, true, false, BranchOptions.EMPTY);
    catalog.createOrReplaceBranch(dorisTable, info3);
    assertSnapshotRef(icebergTable.refs().get(branch2), icebergTable.currentSnapshot().snapshotId(), true, null, null, null);
    // update branch2
    BranchOptions brOps = new BranchOptions(Optional.empty(), Optional.of(1L), Optional.of(2), Optional.of(3L));
    CreateOrReplaceBranchInfo info5 = new CreateOrReplaceBranchInfo(branch2, true, true, false, brOps);
    catalog.createOrReplaceBranch(dorisTable, info5);
    assertSnapshotRef(icebergTable.refs().get(branch2), icebergTable.currentSnapshot().snapshotId(), true, 1L, 2, 3L);
    // total branch:
    //   'main','branch1','branch2'
    Assertions.assertEquals(3, icebergTable.refs().size());
    // insert some data
    addSomeDataIntoIcebergTable();
    addSomeDataIntoIcebergTable();
    addSomeDataIntoIcebergTable();
    addSomeDataIntoIcebergTable();
    snapshots = Lists.newArrayList(icebergTable.snapshots());
    Assertions.assertEquals(6, snapshots.size());
    // create a new branch: branch3
    BranchOptions brOps2 = new BranchOptions(Optional.of(snapshots.get(4).snapshotId()), Optional.of(1L), Optional.of(2), Optional.of(3L));
    CreateOrReplaceBranchInfo info6 = new CreateOrReplaceBranchInfo(branch3, true, true, false, brOps2);
    catalog.createOrReplaceBranch(dorisTable, info6);
    assertSnapshotRef(icebergTable.refs().get(branch3), snapshots.get(4).snapshotId(), true, 1L, 2, 3L);
    // update branch1
    catalog.createOrReplaceBranch(dorisTable, info2);
    assertSnapshotRef(icebergTable.refs().get(branch1), icebergTable.currentSnapshot().snapshotId(), true, null, null, null);
    Assertions.assertEquals(4, icebergTable.refs().size());
}

