    catalog.createOrReplaceBranch(dorisTable, branchInfo2);
    Assertions.assertEquals(5, icebergTable.refs().size());
    Assertions.assertTrue(icebergTable.refs().containsKey(tag1));
    Assertions.assertTrue(icebergTable.refs().get(tag1).isTag());
    Assertions.assertTrue(icebergTable.refs().containsKey(tag2));
    Assertions.assertTrue(icebergTable.refs().get(tag2).isTag());
    Assertions.assertTrue(icebergTable.refs().containsKey(branch1));
    Assertions.assertTrue(icebergTable.refs().get(branch1).isBranch());
    Assertions.assertTrue(icebergTable.refs().containsKey(branch2));
    Assertions.assertTrue(icebergTable.refs().get(branch2).isBranch());
    // drop tag with branch interface, will fail
    DropBranchInfo dropBranchInfoWithTag1 = new DropBranchInfo(tag1, false);
    DropBranchInfo dropBranchInfoIfExistsWithTag1 = new DropBranchInfo(tag1, true);
    Assertions.assertThrows(RuntimeException.class, () -> catalog.dropBranch(dorisTable, dropBranchInfoWithTag1));
    Assertions.assertThrows(RuntimeException.class, () -> catalog.dropBranch(dorisTable, dropBranchInfoIfExistsWithTag1));
    // drop branch with tag interface, will fail
    DropTagInfo dropTagInfoWithBranch1 = new DropTagInfo(branch1, false);
    DropTagInfo dropTagInfoWithBranchIfExists1 = new DropTagInfo(branch1, true);
    Assertions.assertThrows(RuntimeException.class, () -> catalog.dropTag(dorisTable, dropTagInfoWithBranch1));
    Assertions.assertThrows(RuntimeException.class, () -> catalog.dropTag(dorisTable, dropTagInfoWithBranchIfExists1));
    // drop not exists tag
    DropTagInfo dropTagInfoWithNotExistsTag1 = new DropTagInfo(tagNotExists, true);
    DropTagInfo dropTagInfoWithNotExistsTag2 = new DropTagInfo(tagNotExists, false);
    DropTagInfo dropTagInfoWithNotExistsBranch1 = new DropTagInfo(branchNotExists, true);
    DropTagInfo dropTagInfoWithNotExistsBranch2 = new DropTagInfo(branchNotExists, false);
    catalog.dropTag(dorisTable, dropTagInfoWithNotExistsTag1);
    Assertions.assertThrows(RuntimeException.class, () -> catalog.dropTag(dorisTable, dropTagInfoWithNotExistsTag2));
    catalog.dropTag(dorisTable, dropTagInfoWithNotExistsBranch1);
    Assertions.assertThrows(RuntimeException.class, () -> catalog.dropTag(dorisTable, dropTagInfoWithNotExistsBranch2));
    // drop not exists branch
    DropBranchInfo dropBranchInfoWithNotExistsTag1 = new DropBranchInfo(tagNotExists, true);
    DropBranchInfo dropBranchInfoWithNotExistsTag2 = new DropBranchInfo(tagNotExists, false);
    DropBranchInfo dropBranchInfoIfExistsWithBranch1 = new DropBranchInfo(branchNotExists, true);
    DropBranchInfo dropBranchInfoIfExistsWithBranch2 = new DropBranchInfo(branchNotExists, false);
    catalog.dropBranch(dorisTable, dropBranchInfoWithNotExistsTag1);
    Assertions.assertThrows(RuntimeException.class, () -> catalog.dropBranch(dorisTable, dropBranchInfoWithNotExistsTag2));
    catalog.dropBranch(dorisTable, dropBranchInfoIfExistsWithBranch1);
    Assertions.assertThrows(RuntimeException.class, () -> catalog.dropBranch(dorisTable, dropBranchInfoIfExistsWithBranch2));
    // drop branch1 and branch2
    DropBranchInfo dropBranchInfoWithBranch1 = new DropBranchInfo(branch1, false);
    DropBranchInfo dropBranchInfoWithBranch2 = new DropBranchInfo(branch2, true);
    catalog.dropBranch(dorisTable, dropBranchInfoWithBranch1);
    catalog.dropBranch(dorisTable, dropBranchInfoWithBranch2);
    // drop tag1 and tag2
    DropTagInfo dropTagInfoWithTag1 = new DropTagInfo(tag1, false);
    DropTagInfo dropTagInfoWithTag2 = new DropTagInfo(tag2, true);
    catalog.dropTag(dorisTable, dropTagInfoWithTag1);
    catalog.dropTag(dorisTable, dropTagInfoWithTag2);
    Assertions.assertEquals(1, icebergTable.refs().size());
}

@Test
public void testIsSupportedPartitionTable() {
    IcebergExternalDatabase database = new IcebergExternalDatabase(mockCatalog, 1L, "2", "2");
    IcebergExternalTable table = new IcebergExternalTable(1, "1", "1", mockCatalog, database);
    // Create a spy to be able to mock the getIcebergTable method and the makeSureInitialized method
    IcebergExternalTable spyTable = Mockito.spy(table);
    Mockito.doReturn(icebergTable).when(spyTable).getIcebergTable();
    // Simulate the makeSureInitialized method as a no-op to avoid calling the parent class implementation
    Mockito.doNothing().when(spyTable).makeSureInitialized();
    Map<Integer, PartitionSpec> specs = Maps.newHashMap();
    // Test null
    specs.put(0, null);
    Mockito.when(icebergTable.specs()).thenReturn(specs);
    Assertions.assertFalse(spyTable.isValidRelatedTableCached());
    Assertions.assertFalse(spyTable.isValidRelatedTable());
    Mockito.verify(icebergTable, Mockito.times(1)).specs();
    Assertions.assertTrue(spyTable.isValidRelatedTableCached());
    Assertions.assertFalse(spyTable.validRelatedTableCache());
    // Test spec fields are empty.
    specs.put(0, spec);
    spyTable.setIsValidRelatedTableCached(false);
    Assertions.assertFalse(spyTable.isValidRelatedTableCached());
    Mockito.when(icebergTable.specs()).thenReturn(specs);
    List<PartitionField> fields = Lists.newArrayList();
    Mockito.when(spec.fields()).thenReturn(fields);
    Assertions.assertFalse(spyTable.isValidRelatedTable());
    Mockito.verify(spec, Mockito.times(1)).fields();
    Assertions.assertTrue(spyTable.isValidRelatedTableCached());
    Assertions.assertFalse(spyTable.validRelatedTableCache());
    // Test spec fields are more than 1.
    specs.put(0, spec);
    spyTable.setIsValidRelatedTableCached(false);
    Assertions.assertFalse(spyTable.isValidRelatedTableCached());
    Mockito.when(icebergTable.specs()).thenReturn(specs);
    fields.add(null);
    fields.add(null);
    Mockito.when(spec.fields()).thenReturn(fields);
    Assertions.assertFalse(spyTable.isValidRelatedTable());
    Mockito.verify(spec, Mockito.times(2)).fields();
    Assertions.assertTrue(spyTable.isValidRelatedTableCached());
    Assertions.assertFalse(spyTable.validRelatedTableCache());
    fields.clear();
    // Test true
    fields.add(field);
    spyTable.setIsValidRelatedTableCached(false);
    Assertions.assertFalse(spyTable.isValidRelatedTableCached());
    Mockito.when(icebergTable.schema()).thenReturn(schema);
    Mockito.when(schema.findColumnName(ArgumentMatchers.anyInt())).thenReturn("col1");
    Mockito.when(field.transform()).thenReturn(new Hours());
    Mockito.when(field.sourceId()).thenReturn(1);
    Assertions.assertTrue(spyTable.isValidRelatedTable());
    Assertions.assertTrue(spyTable.isValidRelatedTableCached());
    Assertions.assertTrue(spyTable.validRelatedTableCache());
    Mockito.verify(schema, Mockito.times(1)).findColumnName(ArgumentMatchers.anyInt());
    Mockito.when(field.transform()).thenReturn(new Days());
    Mockito.when(field.sourceId()).thenReturn(1);
    spyTable.setIsValidRelatedTableCached(false);
    Assertions.assertFalse(spyTable.isValidRelatedTableCached());
    Assertions.assertTrue(spyTable.isValidRelatedTable());
    Mockito.when(field.transform()).thenReturn(new Months());
    Mockito.when(field.sourceId()).thenReturn(1);
    spyTable.setIsValidRelatedTableCached(false);
    Assertions.assertFalse(spyTable.isValidRelatedTableCached());
    Assertions.assertTrue(spyTable.isValidRelatedTable());
    Assertions.assertTrue(spyTable.isValidRelatedTableCached());
    Assertions.assertTrue(spyTable.validRelatedTableCache());
}

@Test
public void testGetPartitionRange() throws AnalysisException {
    Column c = new Column("ts", PrimitiveType.DATETIMEV2);
    List<Column> partitionColumns = Lists.newArrayList(c);
    // Test null partition value
    Range<PartitionKey> nullRange = IcebergUtils.getPartitionRange(null, "hour", partitionColumns);
    Assertions.assertEquals("0000-01-01 00:00:00", nullRange.lowerEndpoint().getPartitionValuesAsStringList().get(0));
    Assertions.assertEquals("0000-01-01 00:00:01", nullRange.upperEndpoint().getPartitionValuesAsStringList().get(0));
    // Test hour transform.
    Range<PartitionKey> hour = IcebergUtils.getPartitionRange("100", "hour", partitionColumns);
    PartitionKey lowKey = hour.lowerEndpoint();
    PartitionKey upKey = hour.upperEndpoint();
    Assertions.assertEquals("1970-01-05 04:00:00", lowKey.getPartitionValuesAsStringList().get(0));
    Assertions.assertEquals("1970-01-05 05:00:00", upKey.getPartitionValuesAsStringList().get(0));
    // Test day transform.
    Range<PartitionKey> day = IcebergUtils.getPartitionRange("100", "day", partitionColumns);
    lowKey = day.lowerEndpoint();
    upKey = day.upperEndpoint();
    Assertions.assertEquals("1970-04-11 00:00:00", lowKey.getPartitionValuesAsStringList().get(0));
    Assertions.assertEquals("1970-04-12 00:00:00", upKey.getPartitionValuesAsStringList().get(0));
    // Test month transform.
    Range<PartitionKey> month = IcebergUtils.getPartitionRange("100", "month", partitionColumns);
    lowKey = month.lowerEndpoint();
    upKey = month.upperEndpoint();
    Assertions.assertEquals("1978-05-01 00:00:00", lowKey.getPartitionValuesAsStringList().get(0));
    Assertions.assertEquals("1978-06-01 00:00:00", upKey.getPartitionValuesAsStringList().get(0));
    // Test year transform.
    Range<PartitionKey> year = IcebergUtils.getPartitionRange("100", "year", partitionColumns);
    lowKey = year.lowerEndpoint();
    upKey = year.upperEndpoint();
    Assertions.assertEquals("2070-01-01 00:00:00", lowKey.getPartitionValuesAsStringList().get(0));
    Assertions.assertEquals("2071-01-01 00:00:00", upKey.getPartitionValuesAsStringList().get(0));
    // Test unsupported transform
    Exception exception = Assertions.assertThrows(RuntimeException.class, () -> {
        IcebergUtils.getPartitionRange("100", "bucket", partitionColumns);
    });
    Assertions.assertEquals("Unsupported transform bucket", exception.getMessage());
}

