@Test
public void testGetMetaObjConcurrent() throws InterruptedException {
    // Create a CountDownLatch to track cache loading invocations
    CountDownLatch loadLatch = new CountDownLatch(1);
    AtomicInteger loadCount = new AtomicInteger(0);
    // Create a custom cache loader that counts invocations and simulates slow loading
    CacheLoader<String, Optional<String>> metaObjCacheLoader = key -> {
        loadCount.incrementAndGet();
        // Simulate slow loading
        Thread.sleep(100);
        loadLatch.countDown();
        return Optional.of("loaded_" + key);
    };
    // Create a new MetaCache instance with our custom loader
    MetaCache<String> testCache = new MetaCache<>("testCache", Executors.newCachedThreadPool(), OptionalLong.of(1), OptionalLong.of(1), 100, key -> Lists.newArrayList(), metaObjCacheLoader, (key, value, cause) -> {
    });
    // Test concurrent access to non-existent key
    ExecutorService executor = Executors.newFixedThreadPool(10);
    final CountDownLatch startLatch = new CountDownLatch(1);
    final CountDownLatch finishLatch = new CountDownLatch(10);
    for (int i = 0; i < 10; i++) {
        executor.submit(() -> {
            try {
                startLatch.await();
                Optional<String> result = testCache.getMetaObj("concurrent_key", 1L);
                Assert.assertTrue(result.isPresent());
                Assert.assertEquals("loaded_concurrent_key", result.get());
            } catch (Exception e) {
                Assert.fail("Exception occurred: " + e.getMessage());
            } finally {
                finishLatch.countDown();
            }
        });
    }
    // Start all threads
    startLatch.countDown();
    // Wait for all threads to complete
    finishLatch.await(5, TimeUnit.SECONDS);
    // Wait for cache loading to complete
    loadLatch.await(5, TimeUnit.SECONDS);
    // Verify that cache loader was invoked exactly once
    Assert.assertEquals(1, loadCount.get());
    // Test concurrent access to existing but empty key
    loadCount.set(0);
    CountDownLatch loadLatch2 = new CountDownLatch(1);
    CacheLoader<String, Optional<String>> metaObjCacheLoader2 = key -> {
        loadCount.incrementAndGet();
        // Simulate slow loading
        Thread.sleep(100);
        loadLatch2.countDown();
        return Optional.of("loaded_" + key);
    };
    // Create another MetaCache instance
    MetaCache<String> testCache2 = new MetaCache<>("testCache2", Executors.newCachedThreadPool(), OptionalLong.of(1), OptionalLong.of(1), 100, key -> Lists.newArrayList(), metaObjCacheLoader2, (key, value, cause) -> {
    });
    // Manually put an empty Optional into cache
    testCache2.getMetaObjCache().put("empty_concurrent_key", Optional.empty());
    // Reset latches for second test
    final CountDownLatch startLatch2 = new CountDownLatch(1);
    final CountDownLatch finishLatch2 = new CountDownLatch(10);
    for (int i = 0; i < 10; i++) {
        executor.submit(() -> {
            try {
                startLatch2.await();
                Optional<String> result = testCache2.getMetaObj("empty_concurrent_key", 2L);
                Assert.assertTrue(result.isPresent());
                Assert.assertEquals("loaded_empty_concurrent_key", result.get());
            } catch (Exception e) {
                Assert.fail("Exception occurred: " + e.getMessage());
            } finally {
                finishLatch2.countDown();
            }
        });
    }
    // Start all threads
    startLatch2.countDown();
    // Wait for all threads to complete
    finishLatch2.await(5, TimeUnit.SECONDS);
    // Wait for cache loading to complete
    loadLatch2.await(5, TimeUnit.SECONDS);
    // Verify that cache loader was invoked exactly once
    Assert.assertEquals(1, loadCount.get());
    executor.shutdown();
    executor.awaitTermination(1, TimeUnit.SECONDS);
}

@Test
public void testSerialization() throws Exception {
    // 1. Write objects to file
    MetaIdMappingsLog log1 = new MetaIdMappingsLog();
    Path path = Files.createFile(Paths.get("./metaIdMappingsLogTest.txt"));
    try (DataOutputStream dos = new DataOutputStream(Files.newOutputStream(path))) {
        log1.setFromHmsEvent(true);
        log1.setLastSyncedEventId(-1L);
        log1.setCatalogId(1L);
        log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_ADD, MetaIdMappingsLog.META_OBJECT_TYPE_DATABASE, "db1", ExternalMetaIdMgr.nextMetaId()));
        log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_DELETE, MetaIdMappingsLog.META_OBJECT_TYPE_TABLE, "db1", "tbl1", ExternalMetaIdMgr.nextMetaId()));
        log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_DELETE, MetaIdMappingsLog.META_OBJECT_TYPE_TABLE, "db1", "tbl2", ExternalMetaIdMgr.nextMetaId()));
        log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_DELETE, MetaIdMappingsLog.META_OBJECT_TYPE_DATABASE, "db2"));
        log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_ADD, MetaIdMappingsLog.META_OBJECT_TYPE_PARTITION, "db1", "tbl1", "p1", ExternalMetaIdMgr.nextMetaId()));
        log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_ADD, MetaIdMappingsLog.META_OBJECT_TYPE_PARTITION, "db1", "tbl1", "p2", ExternalMetaIdMgr.nextMetaId()));
        log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_DELETE, MetaIdMappingsLog.META_OBJECT_TYPE_DATABASE, "db2"));
        log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_DELETE, MetaIdMappingsLog.META_OBJECT_TYPE_TABLE, "db1", "tbl1", ExternalMetaIdMgr.nextMetaId()));
        log1.addMetaIdMapping(new MetaIdMappingsLog.MetaIdMapping(MetaIdMappingsLog.OPERATION_TYPE_DELETE, MetaIdMappingsLog.META_OBJECT_TYPE_PARTITION, "db1", "tbl1", "p2", ExternalMetaIdMgr.nextMetaId()));
        log1.write(dos);
        dos.flush();
    } catch (Throwable throwable) {
        throwable.printStackTrace();
        Files.deleteIfExists(path);
        Assertions.fail();
    }
    // 2. Read objects from file
    MetaIdMappingsLog log2;
    try (DataInputStream dis = new DataInputStream(Files.newInputStream(path))) {
        log2 = MetaIdMappingsLog.read(dis);
        Assertions.assertEquals(log1, log2);
    } catch (Throwable throwable) {
        throwable.printStackTrace();
        Assertions.fail();
    } finally {
        Files.deleteIfExists(path);
    }
}

