@Test
void testAddToQueueConcurrentAccess() throws Exception {
    Multimap<Backend, Split> batch = ArrayListMultimap.create();
    batch.put(mockBackend, mockSplit);
    new Expectations() {

        {
            mockBackendPolicy.computeScanRangeAssignment((List<Split>) any);
