@Test
public void testCompoundPredicate() throws AnalysisException {
    // construct slotRefs and literalLists
    List<SlotRef> slotRefs = mockSlotRefs();
    List<LiteralExpr> literalList = mockLiteralExpr();
    // valid expr
    List<Expr> validExprs = Lists.newArrayList();
    for (int i = 0; i < slotRefs.size(); i++) {
        BinaryPredicate expr = new BinaryPredicate(BinaryPredicate.Operator.EQ, slotRefs.get(i), literalList.get(i));
        validExprs.add(expr);
    }
    // invalid expr
    BinaryPredicate invalidExpr = new BinaryPredicate(BinaryPredicate.Operator.EQ, literalList.get(0), literalList.get(0));
    // AND
    // valid AND valid
    for (int i = 0; i < validExprs.size(); i++) {
        for (int j = 0; j < validExprs.size(); j++) {
            CompoundPredicate andPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, validExprs.get(i), validExprs.get(j));
            trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(andPredicate);
        }
    }
    // valid AND invalid
    CompoundPredicate andPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, validExprs.get(0), invalidExpr);
    trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(andPredicate);
    // invalid AND valid
    andPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, invalidExpr, validExprs.get(0));
    trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(andPredicate);
    // invalid AND invalid
    andPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, invalidExpr, invalidExpr);
    try {
        trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(andPredicate);
    } catch (AnalysisException e) {
        Assert.assertTrue(e.getMessage().contains("Can not convert both sides of compound predicate"));
    }
    // OR
    // valid OR valid
    for (int i = 0; i < validExprs.size(); i++) {
        for (int j = 0; j < validExprs.size(); j++) {
            CompoundPredicate orPredicate = new CompoundPredicate(CompoundPredicate.Operator.OR, validExprs.get(i), validExprs.get(j));
            trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(orPredicate);
        }
    }
    // // valid OR valid
    try {
        CompoundPredicate orPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, validExprs.get(0), invalidExpr);
        trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(orPredicate);
    } catch (AnalysisException e) {
        Assert.assertTrue(e.getMessage().contains("slotRef is null in binaryPredicateConverter"));
    }
}

