@Test
public void testAlterMTMV() throws Exception {
    createDatabaseAndUse("test");
    createTable("CREATE TABLE `stu` (`sid` int(32) NULL, `sname` varchar(32) NULL)\n" + "ENGINE=OLAP\n" + "DUPLICATE KEY(`sid`)\n" + "DISTRIBUTED BY HASH(`sid`) BUCKETS 1\n" + "PROPERTIES ('replication_allocation' = 'tag.location.default: 1')");
    createMvByNereids("CREATE MATERIALIZED VIEW mv_a BUILD IMMEDIATE REFRESH COMPLETE ON COMMIT\n" + "DISTRIBUTED BY HASH(`sid`) BUCKETS 1\n" + "PROPERTIES ('replication_allocation' = 'tag.location.default: 1') " + "AS select * from stu limit 1");
    alterMv("ALTER MATERIALIZED VIEW mv_a RENAME mv_b");
    MTMVRelationManager relationManager = Env.getCurrentEnv().getMtmvService().getRelationManager();
    Table table = Env.getCurrentInternalCatalog().getDb("test").get().getTableOrMetaException("stu");
    Set<MTMV> allMTMVs = relationManager.getCandidateMTMVs(Lists.newArrayList(new BaseTableInfo(table)));
    boolean hasMvA = false;
    boolean hasMvB = false;
    for (MTMV mtmv : allMTMVs) {
        if ("mv_a".equals(mtmv.getName())) {
            hasMvA = true;
        }
        if ("mv_b".equals(mtmv.getName())) {
            hasMvB = true;
        }
    }
    Assertions.assertFalse(hasMvA);
    Assertions.assertTrue(hasMvB);
    createTable("CREATE TABLE `stu1` (`sid` int(32) NULL, `sname` varchar(32) NULL)\n" + "ENGINE=OLAP\n" + "DUPLICATE KEY(`sid`)\n" + "DISTRIBUTED BY HASH(`sid`) BUCKETS 1\n" + "PROPERTIES ('replication_allocation' = 'tag.location.default: 1')");
    DdlException exception = Assertions.assertThrows(DdlException.class, () -> alterTableSync("ALTER TABLE stu1 REPLACE WITH TABLE mv_b PROPERTIES('swap' = 'true')"));
    Assertions.assertEquals("errCode = 2, detailMessage = replace table[mv_b] cannot be a materialized view", exception.getMessage());
}

@Test
public void testAlterMTMV() throws Exception {
    createDatabaseAndUse("mtmv_concurrent_test");
    createTable("CREATE TABLE `stu` (`sid` int(32) NULL, `sname` varchar(32) NULL)\n" + "ENGINE=OLAP\n" + "DUPLICATE KEY(`sid`)\n" + "DISTRIBUTED BY HASH(`sid`) BUCKETS 1\n" + "PROPERTIES ('replication_allocation' = 'tag.location.default: 1')");
    createMvByNereids("CREATE MATERIALIZED VIEW mv_a BUILD DEFERRED REFRESH COMPLETE ON MANUAL\n" + "DISTRIBUTED BY HASH(`sid`) BUCKETS 1\n" + "PROPERTIES ('replication_allocation' = 'tag.location.default: 1') " + "AS select * from stu limit 1");
    MTMVRelationManager relationManager = Env.getCurrentEnv().getMtmvService().getRelationManager();
    Table table = Env.getCurrentInternalCatalog().getDb("mtmv_concurrent_test").get().getTableOrMetaException("stu");
    BaseTableInfo baseTableInfo = new BaseTableInfo(table);
    MTMV mtmv = (MTMV) Env.getCurrentInternalCatalog().getDb("mtmv_concurrent_test").get().getTableOrMetaException("mv_a");
    MTMVRelation relation = mtmv.getRelation();
    Set<BaseTableInfo> mtmvsByBaseTable = relationManager.getMtmvsByBaseTable(baseTableInfo);
    Assertions.assertEquals(1, mtmvsByBaseTable.size());
    MTMVTask mtmvTask = new MTMVTask(mtmv, relation, null);
    mtmvTask.setStatus(TaskStatus.SUCCESS);
    // Create threads for concurrent operations
    Thread dropThread = new Thread(() -> {
        try {
            dropMvByNereids("drop materialized view mv_a");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    });
    Thread refreshThread = new Thread(() -> {
        relationManager.refreshComplete(mtmv, relation, mtmvTask);
    });
    // Start both threads
    dropThread.start();
    refreshThread.start();
    // Wait for both threads to complete
    dropThread.join();
    refreshThread.join();
    mtmvsByBaseTable = relationManager.getMtmvsByBaseTable(baseTableInfo);
    Assertions.assertEquals(0, mtmvsByBaseTable.size());
}

@Test
public void testAddHistoryTask() {
    int originalCount = Config.max_persistence_task_count;
    Config.max_persistence_task_count = 0;
    MTMVJobInfo jobInfo = new MTMVJobInfo("dummyJob");
    jobInfo.addHistoryTask(new MTMVTask());
    Assert.assertEquals(0, jobInfo.getHistoryTasks().size());
    Config.max_persistence_task_count = 2;
    for (int i = 0; i < 3; i++) {
        jobInfo.addHistoryTask(new MTMVTask());
    }
    Assert.assertEquals(2, jobInfo.getHistoryTasks().size());
    Config.max_persistence_task_count = 1;
    jobInfo.addHistoryTask(new MTMVTask());
    Assert.assertEquals(1, jobInfo.getHistoryTasks().size());
    Config.max_persistence_task_count = originalCount;
}

