@Test
public void testPartitionSync() {
    // normal
    boolean sync = refreshSnapshot.equalsWithRelatedPartition(mvExistPartitionName, relatedExistPartitionName, new MTMVVersionSnapshot(correctVersion, 0));
    Assert.assertTrue(sync);
    // non exist mv partition
    sync = refreshSnapshot.equalsWithRelatedPartition("mvp2", relatedExistPartitionName, new MTMVVersionSnapshot(correctVersion, 0));
    Assert.assertFalse(sync);
    // non exist related partition
    sync = refreshSnapshot.equalsWithRelatedPartition(mvExistPartitionName, "p2", new MTMVVersionSnapshot(correctVersion, 0));
    Assert.assertFalse(sync);
    // snapshot value not equal
    sync = refreshSnapshot.equalsWithRelatedPartition(mvExistPartitionName, relatedExistPartitionName, new MTMVVersionSnapshot(2L, 0));
    Assert.assertFalse(sync);
    // snapshot type not equal
    sync = refreshSnapshot.equalsWithRelatedPartition(mvExistPartitionName, relatedExistPartitionName, new MTMVTimestampSnapshot(correctVersion));
    Assert.assertFalse(sync);
}

@Test
public void testTableSync() {
    // normal
