@Test
public void testGenerateMTMVPartitionSyncConfigByProperties() throws AnalysisException {
    MTMVRelatedPartitionDescSyncLimitGenerator generator = new MTMVRelatedPartitionDescSyncLimitGenerator();
    Map<String, String> mvProperties = Maps.newHashMap();
    MTMVPartitionSyncConfig config = generator.generateMTMVPartitionSyncConfigByProperties(mvProperties);
    Assert.assertEquals(-1, config.getSyncLimit());
    Assert.assertFalse(config.getDateFormat().isPresent());
    Assert.assertEquals(MTMVPartitionSyncTimeUnit.DAY, config.getTimeUnit());
    mvProperties.put(PropertyAnalyzer.PROPERTIES_PARTITION_SYNC_LIMIT, "1");
    config = generator.generateMTMVPartitionSyncConfigByProperties(mvProperties);
    Assert.assertEquals(1, config.getSyncLimit());
    Assert.assertFalse(config.getDateFormat().isPresent());
    Assert.assertEquals(MTMVPartitionSyncTimeUnit.DAY, config.getTimeUnit());
    mvProperties.put(PropertyAnalyzer.PROPERTIES_PARTITION_TIME_UNIT, "month");
    config = generator.generateMTMVPartitionSyncConfigByProperties(mvProperties);
    Assert.assertEquals(1, config.getSyncLimit());
    Assert.assertFalse(config.getDateFormat().isPresent());
    Assert.assertEquals(MTMVPartitionSyncTimeUnit.MONTH, config.getTimeUnit());
    mvProperties.put(PropertyAnalyzer.PROPERTIES_PARTITION_DATE_FORMAT, "%Y%m%d");
    config = generator.generateMTMVPartitionSyncConfigByProperties(mvProperties);
    Assert.assertEquals(1, config.getSyncLimit());
    Assert.assertEquals("%Y%m%d", config.getDateFormat().get());
    Assert.assertEquals(MTMVPartitionSyncTimeUnit.MONTH, config.getTimeUnit());
}

@Test
public void testGetNowTruncSubSec() throws AnalysisException {
    MTMVRelatedPartitionDescSyncLimitGenerator generator = new MTMVRelatedPartitionDescSyncLimitGenerator();
    DateTimeV2Literal dateTimeLiteral = new DateTimeV2Literal("2020-02-03 20:10:10");
    new Expectations() {

        {
            dateTimeAcquire.now();
            minTimes = 0;
            result = dateTimeLiteral;
        }
    };
    long nowTruncSubSec = generator.getNowTruncSubSec(MTMVPartitionSyncTimeUnit.DAY, 1);
    // 2020-02-03
    Assert.assertEquals(1580659200L, nowTruncSubSec);
    nowTruncSubSec = generator.getNowTruncSubSec(MTMVPartitionSyncTimeUnit.MONTH, 1);
    // 2020-02-01
    Assert.assertEquals(1580486400L, nowTruncSubSec);
    nowTruncSubSec = generator.getNowTruncSubSec(MTMVPartitionSyncTimeUnit.YEAR, 1);
    // 2020-01-01
    Assert.assertEquals(1577808000L, nowTruncSubSec);
    nowTruncSubSec = generator.getNowTruncSubSec(MTMVPartitionSyncTimeUnit.MONTH, 3);
    // 2019-12-01
    Assert.assertEquals(1575129600L, nowTruncSubSec);
    nowTruncSubSec = generator.getNowTruncSubSec(MTMVPartitionSyncTimeUnit.DAY, 4);
    // 2020-01-31
    Assert.assertEquals(1580400000L, nowTruncSubSec);
}

@Test
public void testGetMtmvsByBaseTableOneLevel() {
    // mock mv2==>mv1,t3; mv1==>t4
    MTMVRelationManager manager = new MTMVRelationManager();
    MTMVRelation mv2Relation = new MTMVRelation(Sets.newHashSet(mv1, t3, t4), Sets.newHashSet(mv1, t3), Sets.newHashSet());
    MTMVRelation mv1Relation = new MTMVRelation(Sets.newHashSet(t4), Sets.newHashSet(t4), Sets.newHashSet());
    manager.refreshMTMVCache(mv2Relation, mv2);
    manager.refreshMTMVCache(mv1Relation, mv1);
    // should return mv2
    Set<BaseTableInfo> mv1OneLevel = manager.getMtmvsByBaseTableOneLevel(mv1);
    Assert.assertTrue(CollectionUtils.isEqualCollection(Sets.newHashSet(mv2), mv1OneLevel));
    // should return mv2
    Set<BaseTableInfo> t3OneLevel = manager.getMtmvsByBaseTableOneLevel(t3);
    Assert.assertTrue(CollectionUtils.isEqualCollection(Sets.newHashSet(mv2), t3OneLevel));
    // should return mv1
    Set<BaseTableInfo> t4OneLevel = manager.getMtmvsByBaseTableOneLevel(t4);
    Assert.assertTrue(CollectionUtils.isEqualCollection(Sets.newHashSet(mv1), t4OneLevel));
    // update mv2 only use t3,remove mv1
    mv2Relation = new MTMVRelation(Sets.newHashSet(t3), Sets.newHashSet(t3), Sets.newHashSet());
    manager.refreshMTMVCache(mv2Relation, mv2);
    // should return empty
    mv1OneLevel = manager.getMtmvsByBaseTableOneLevel(mv1);
    Assert.assertTrue(CollectionUtils.isEqualCollection(Sets.newHashSet(), mv1OneLevel));
    // should return mv2
    t3OneLevel = manager.getMtmvsByBaseTableOneLevel(t3);
    Assert.assertTrue(CollectionUtils.isEqualCollection(Sets.newHashSet(mv2), t3OneLevel));
    // should return mv1
    t4OneLevel = manager.getMtmvsByBaseTableOneLevel(t4);
    Assert.assertTrue(CollectionUtils.isEqualCollection(Sets.newHashSet(mv1), t4OneLevel));
}

