    // Create a scheduler with small max connections
    ConnectScheduler scheduler = new ConnectScheduler(1000, 2);
    // Setup expectations
    new Expectations() {

        {
            // Arrow flight sql not check the number of user connections.
            // mockEnv.getAuth();
