            result = scheduler;
            UserIdentity userIdentity = UserIdentity.createAnalyzedUserIdentWithIp("test_user", "%");
            FlightTokenDetails tokenDetails = new FlightTokenDetails("test_token", "test_user", System.currentTimeMillis(), // expires in 1 hour
