        e.printStackTrace();
        Assert.fail();
    }
    Assert.assertFalse(accessManager.checkCloudPriv(userIdentity, computeGroup1, PrivPredicate.USAGE, ResourceTypeEnum.CLUSTER));
    Assert.assertFalse(accessManager.checkGlobalPriv(userIdentity, PrivPredicate.USAGE));
    // 3.1 grant 'notBelongToResourcePrivileges' on cluster 'cg1' to 'testUser'@'%'
    for (int i = 0; i < Privilege.notBelongToResourcePrivileges.length; i++) {
        List<AccessPrivilegeWithCols> notAllowedPrivileges = Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.fromName(Privilege.notBelongToResourcePrivileges[i].getName())));
        grantResourcePrivilegeCommand = new GrantResourcePrivilegeCommand(notAllowedPrivileges, Optional.of(resourcePattern), Optional.empty(), Optional.of(""), Optional.of(userIdentity));
        try {
            grantResourcePrivilegeCommand.validate();
            Assert.fail(String.format("Can not grant/revoke %s to/from any other users or roles", Privilege.notBelongToWorkloadGroupPrivileges[i]));
        } catch (AnalysisException e) {
            e.printStackTrace();
        }
    }
    // 4. drop user
    DropUserCommand dropUserCommand = new DropUserCommand(userIdentity, true);
    try {
        dropUserCommand.doRun(connectContext, null);
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail();
    }
    // ------ grant|revoke cluster to|from role ------
    // 1. create role
    String createRoleSql = "CREATE ROLE role1";
    NereidsParser nereidsParser = new NereidsParser();
    LogicalPlan logicalRolePlan1 = nereidsParser.parseSingle(createRoleSql);
    Assertions.assertDoesNotThrow(() -> ((CreateRoleCommand) logicalRolePlan1).run(connectContext, null));
    String grantCgPrivilegeSql = "GRANT usage_priv ON cluster 'cg1' to role 'role1'";
