public void testSimplestScene() {
    Plan leaf = new UnboundRelation(StatementScopeIdGenerator.newRelationId(), Lists.newArrayList("test"));
    LogicalProject<Plan> project = new LogicalProject<>(ImmutableList.of(new SlotReference("name", StringType.INSTANCE, true, ImmutableList.of("test"))), leaf);
