    LogicalOlapScan scanD = new LogicalOlapScan(StatementScopeIdGenerator.newRelationId(), tableD);
    LogicalJoin<LogicalOlapScan, LogicalOlapScan> leftJoin = new LogicalJoin<>(JoinType.CROSS_JOIN, scanA, scanB, null);
    LogicalJoin<LogicalOlapScan, LogicalOlapScan> rightJoin = new LogicalJoin<>(JoinType.CROSS_JOIN, scanC, scanD, null);
    LogicalJoin topJoin = new LogicalJoin<>(JoinType.CROSS_JOIN, leftJoin, rightJoin, null);
    PlanChecker.from(connectContext, topJoin).checkGroupNum(7).matches(logicalJoin(logicalJoin(any().when(child -> Objects.equals(child, scanA)), any().when(child -> Objects.equals(child, scanB))).when(left -> Objects.equals(left, leftJoin)), logicalJoin(any().when(child -> Objects.equals(child, scanC)), any().when(child -> Objects.equals(child, scanD))).when(right -> Objects.equals(right, rightJoin))).when(root -> Objects.equals(root, topJoin)));
