@Test
public void parseSetOperation() {
    String union = "select * from t1 union select * from t2 union all select * from t3";
    NereidsParser nereidsParser = new NereidsParser();
    LogicalPlan logicalPlan = nereidsParser.parseSingle(union);
    System.out.println(logicalPlan.treeString());
    String union1 = "select * from t1 union (select * from t2 union all select * from t3)";
    LogicalPlan logicalPlan1 = nereidsParser.parseSingle(union1);
    System.out.println(logicalPlan1.treeString());
    String union2 = "(SELECT K1, K2, K3, K4, K5, K6, K7, K8, K9, K10, K11 FROM test WHERE K1 > 0)" + " UNION ALL (SELECT 1, 2, 3, 4, 3.14, 'HELLO', 'WORLD', 0.0, 1.1, CAST('1989-03-21' AS DATE), CAST('1989-03-21 13:00:00' AS DATETIME))" + " UNION ALL (SELECT K1, K2, K3, K4, K5, K6, K7, K8, K9, K10, K11 FROM baseall WHERE K3 > 0)" + " ORDER BY K1, K2, K3, K4";
    LogicalPlan logicalPlan2 = nereidsParser.parseSingle(union2);
    System.out.println(logicalPlan2.treeString());
    String union3 = "select a.k1, a.k2, a.k3, b.k1, b.k2, b.k3 from test a left outer join baseall b" + " on a.k1 = b.k1 and a.k2 > b.k2 union (select a.k1, a.k2, a.k3, b.k1, b.k2, b.k3" + " from test a right outer join baseall b on a.k1 = b.k1 and a.k2 > b.k2)" + " order by isnull(a.k1), 1, 2, 3, 4, 5 limit 65535";
    LogicalPlan logicalPlan3 = nereidsParser.parseSingle(union3);
    System.out.println(logicalPlan3.treeString());
}

@Test
public void testJoinHint() {
    // no hint
    parsePlan("select * from t1 join t2 on t1.keyy=t2.keyy").matches(logicalJoin().when(j -> j.getDistributeHint().distributeType == DistributeType.NONE));
    // valid hint
    parsePlan("select * from t1 join [shuffle] t2 on t1.keyy=t2.keyy").matches(logicalJoin().when(j -> j.getDistributeHint().distributeType == DistributeType.SHUFFLE_RIGHT));
    parsePlan("select * from t1 join [  shuffle ] t2 on t1.keyy=t2.keyy").matches(logicalJoin().when(j -> j.getDistributeHint().distributeType == DistributeType.SHUFFLE_RIGHT));
    parsePlan("select * from t1 join [broadcast] t2 on t1.keyy=t2.keyy").matches(logicalJoin().when(j -> j.getDistributeHint().distributeType == DistributeType.BROADCAST_RIGHT));
    // invalid hint position
    parsePlan("select * from [shuffle] t1 join t2 on t1.keyy=t2.keyy").assertThrowsExactly(ParseException.class);
    // invalid hint content
    parsePlan("select * from t1 join [bucket] t2 on t1.keyy=t2.keyy").assertThrowsExactly(ParseException.class).assertMessageContains("Invalid join hint: bucket(line 1, pos 22)\n" + "\n" + "== SQL ==\n" + "select * from t1 join [bucket] t2 on t1.keyy=t2.keyy\n" + "----------------------^^^");
    // invalid multiple hints
    parsePlan("select * from t1 join [shuffle,broadcast] t2 on t1.keyy=t2.keyy").assertThrowsExactly(ParseException.class);
}

@Test
public void testParseCast() {
    String sql = "SELECT CAST(1 AS DECIMAL(20, 6)) FROM t";
    NereidsParser nereidsParser = new NereidsParser();
    LogicalPlan logicalPlan = (LogicalPlan) nereidsParser.parseSingle(sql).child(0);
    Cast cast = (Cast) logicalPlan.getExpressions().get(0).child(0);
    if (Config.enable_decimal_conversion) {
        DecimalV3Type decimalV3Type = (DecimalV3Type) cast.getDataType();
        Assertions.assertEquals(20, decimalV3Type.getPrecision());
        Assertions.assertEquals(6, decimalV3Type.getScale());
    } else {
        DecimalV2Type decimalV2Type = (DecimalV2Type) cast.getDataType();
        Assertions.assertEquals(20, decimalV2Type.getPrecision());
        Assertions.assertEquals(6, decimalV2Type.getScale());
    }
}

