    checkQueryTopPlanClass("SELECT 1 LIMIT 1", nereidsParser, LogicalLimit.class);
    checkQueryTopPlanClass("SELECT 1 UNION ALL SELECT 1 LIMIT 1", nereidsParser, LogicalLimit.class);
    checkQueryTopPlanClass("(SELECT 1 UNION ALL SELECT 1) LIMIT 1", nereidsParser, LogicalLimit.class);
    checkQueryTopPlanClass("SELECT 1 UNION ALL (SELECT 1 LIMIT 1)", nereidsParser, LogicalUnion.class);
    checkQueryTopPlanClass("SELECT 1 ORDER BY 1 UNION ALL SELECT 1 LIMIT 1", nereidsParser, null);
    checkQueryTopPlanClass("(SELECT 1 ORDER BY 1) UNION ALL (SELECT 1 LIMIT 1)", nereidsParser, LogicalUnion.class);
    checkQueryTopPlanClass("(SELECT 1 ORDER BY 1) UNION ALL SELECT 1 LIMIT 1", nereidsParser, LogicalLimit.class);
}

@Test
public void testBlockSqlAst() {
    String sql = "plan replayer dump select `AD``D` from t1 where a = 1";
    NereidsParser nereidsParser = new NereidsParser();
    LogicalPlan logicalPlan = nereidsParser.parseSingle(sql);
    Config.block_sql_ast_names = "ReplayCommand";
    StmtExecutor.initBlockSqlAstNames();
    StmtExecutor stmtExecutor = new StmtExecutor(new ConnectContext(), "");
    try {
        stmtExecutor.checkSqlBlocked(logicalPlan.getClass());
        Assertions.fail();
    } catch (Exception ignore) {
        // do nothing
    }
    Config.block_sql_ast_names = "CreatePolicyCommand, ReplayCommand";
    StmtExecutor.initBlockSqlAstNames();
    try {
        stmtExecutor.checkSqlBlocked(logicalPlan.getClass());
        Assertions.fail();
    } catch (Exception ignore) {
        // do nothing
    }
    Config.block_sql_ast_names = "";
    StmtExecutor.initBlockSqlAstNames();
    try {
        stmtExecutor.checkSqlBlocked(logicalPlan.getClass());
    } catch (Exception ex) {
        Assertions.fail(ex);
