@Test
public void testPrivilegesAndPolicies() throws Exception {
    FeConstants.runningUnitTest = true;
    String catalogProvider = "org.apache.doris.nereids.privileges.TestCheckPrivileges$CustomCatalogProvider";
    String accessControllerFactory = "org.apache.doris.nereids.privileges.CustomAccessControllerFactory";
    String catalog = "custom_catalog";
    String db = "test_db";
    String failedAccessControllerFactory = "org.apache.doris.nereids.privileges.FailedAccessControllerFactory";
    //try to create catalog with failed access controller
    Assertions.assertThrows(DdlException.class, () -> {
        createCatalog("create catalog " + catalog + " properties(" + " \"type\"=\"test\"," + " \"catalog_provider.class\"=\"" + catalogProvider + "\"," + " \"" + CatalogMgr.ACCESS_CONTROLLER_CLASS_PROP + "\"=\"" + failedAccessControllerFactory + "\"" + ")");
    }, "Failed to init access controller");
    createCatalog("create catalog " + catalog + " properties(" + " \"type\"=\"test\"," + " \"catalog_provider.class\"=\"" + catalogProvider + "\"," + " \"" + CatalogMgr.ACCESS_CONTROLLER_CLASS_PROP + "\"=\"" + accessControllerFactory + "\"" + ")");
    createDatabase("internal_db");
    String table1 = "test_tbl1";
    String table2 = "test_tbl2";
    String table4 = "test_tbl4";
    String user = "test_nereids_privilege_user";
    addUser(user, true);
    useUser(user);
    List<MakeTablePrivileges> privileges = ImmutableList.of(// base table privileges
    MakePrivileges.table(catalog, db, table1).allowSelectTable(user), MakePrivileges.table(catalog, db, table2).allowSelectColumns(user, ImmutableSet.of("id")), // data masking and row policy
    MakePrivileges.table(catalog, db, table4).allowSelectTable(user).addRowPolicy(user, "id = 1").addDataMasking(user, "id", "concat(id, '_****_', id)"));
    AccessControllerManager accessManager = Env.getCurrentEnv().getAccessManager();
    CatalogAccessController catalogAccessController = accessManager.getAccessControllerOrDefault(catalog);
    new Expectations(accessManager) {

        {
            accessManager.getAccessControllerOrDefault("internal");
            minTimes = 0;
            result = catalogAccessController;
        }
    };
    withPrivileges(privileges, () -> {
        // test base table
        {
            // has table privilege
            query("select * from custom_catalog.test_db.test_tbl1");
            // has id column privilege
            query("select id from custom_catalog.test_db.test_tbl2");
            // no name column privilege, throw exception:
            //
            // Permission denied: user ['test_nereids_privilege_user'@'%'] does not have privilege for
            // [priv predicate: OR, Admin_priv Select_priv ] command on
            // [custom_catalog].[test_db].[test_tbl2].[name]
            Assertions.assertThrows(AnalysisException.class, () -> query("select * from custom_catalog.test_db.test_tbl2"));
            // no table privilege
            Assertions.assertThrows(AnalysisException.class, () -> query("select * from custom_catalog.test_db.test_tbl3"));
        }
        // test row policy with data masking
        {
            Function<NamedExpression, Boolean> checkId = (NamedExpression ne) -> {
                if (!(ne instanceof Alias) || !ne.getName().equals("id")) {
                    return false;
                }
                return ne.child(0).toSql().equals("'1_****_1'");
            };
            PlanChecker.from(connectContext).parse("select id," + "  test_tbl4.id," + "  test_db.test_tbl4.id, " + "  custom_catalog.test_db.test_tbl4.id, " + "  * " + "from custom_catalog.test_db.test_tbl4").analyze().rewrite().matches(logicalProject(logicalFilter(logicalTestScan()).when(f -> {
                EqualTo predicate = (EqualTo) f.getPredicate();
                return predicate.left() instanceof Slot && predicate.right().equals(new IntegerLiteral((byte) 1));
            })).when(p -> {
                List<NamedExpression> projects = p.getProjects();
                if (!checkId.apply(projects.get(0)) || !checkId.apply(projects.get(1)) || !checkId.apply(projects.get(2)) || !checkId.apply(projects.get(3)) || !checkId.apply(projects.get(4))) {
                    return false;
                }
                return projects.get(5) instanceof Slot && projects.get(5).getName().equals("name");
            }));
            PlanChecker.from(connectContext).parse("select id, t.id, *" + "from custom_catalog.test_db.test_tbl4 t").analyze().rewrite().matches(logicalProject(logicalFilter(logicalTestScan()).when(f -> {
                EqualTo predicate = (EqualTo) f.getPredicate();
                return predicate.left() instanceof Slot && predicate.right().equals(new IntegerLiteral((byte) 1));
            })).when(p -> {
                List<NamedExpression> projects = p.getProjects();
                if (!checkId.apply(projects.get(0)) || !checkId.apply(projects.get(1)) || !checkId.apply(projects.get(2))) {
                    return false;
                }
                return projects.get(3) instanceof Slot && projects.get(3).getName().equals("name");
            }));
        }
    });
}

@Test
void testInnerJoin() {
    PhysicalHashJoin<GroupPlan, GroupPlan> join = new PhysicalHashJoin<>(JoinType.INNER_JOIN, ExpressionUtils.EMPTY_CONDITION, ExpressionUtils.EMPTY_CONDITION, new DistributeHint(DistributeType.NONE), Optional.empty(), logicalProperties, groupPlan, groupPlan);
    GroupExpression groupExpression = new GroupExpression(join);
    new Group(null, groupExpression, null);
    PhysicalProperties left = new PhysicalProperties(new DistributionSpecHash(Lists.newArrayList(new ExprId(0)), ShuffleType.NATURAL, 0, Sets.newHashSet(0L)), new OrderSpec(Lists.newArrayList(new OrderKey(new SlotReference("ignored", IntegerType.INSTANCE), true, true))));
    PhysicalProperties right = new PhysicalProperties(new DistributionSpecHash(Lists.newArrayList(new ExprId(1)), ShuffleType.EXECUTION_BUCKETED, 1, Sets.newHashSet(1L)));
    List<PhysicalProperties> childrenOutputProperties = Lists.newArrayList(left, right);
    ChildOutputPropertyDeriver deriver = new ChildOutputPropertyDeriver(childrenOutputProperties);
    PhysicalProperties result = deriver.getOutputProperties(null, groupExpression);
    Assertions.assertTrue(result.getOrderSpec().getOrderKeys().isEmpty());
    Assertions.assertInstanceOf(DistributionSpecHash.class, result.getDistributionSpec());
    DistributionSpecHash actual = (DistributionSpecHash) result.getDistributionSpec();
    Assertions.assertEquals(ShuffleType.NATURAL, actual.getShuffleType());
    // check merged
    Assertions.assertEquals(2, actual.getExprIdToEquivalenceSet().size());
}

