    DistributionSpecHash natural2 = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.NATURAL, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), natural2Map);
    Map<ExprId, Integer> natural3Map = Maps.newHashMap();
    natural3Map.put(new ExprId(2), 0);
    natural3Map.put(new ExprId(1), 1);
    DistributionSpecHash natural3 = new DistributionSpecHash(Lists.newArrayList(new ExprId(2), new ExprId(1)), ShuffleType.NATURAL, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(2)), Sets.newHashSet(new ExprId(1))), natural3Map);
    DistributionSpecHash require = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.REQUIRE, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), natural2Map);
    DistributionSpecHash storageBucketed = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.STORAGE_BUCKETED, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), natural2Map);
