@Test
void testJoin() {
    // foj doesn't propagate any
    Plan plan = PlanChecker.from(connectContext).analyze("select agg.id from agg full outer join uni " + "on agg.id = uni.id").rewrite().getPlan();
    Assertions.assertFalse(plan.getLogicalProperties().getTrait().isUnique(plan.getOutputSet()));
    // loj propagate unique when right is unique
    plan = PlanChecker.from(connectContext).analyze("select agg.id, uni.id from agg left outer join uni " + "on agg.id = uni.name").rewrite().getPlan();
    Assertions.assertFalse(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(0)));
    plan = PlanChecker.from(connectContext).analyze("select agg.id, uni.id from agg left outer join uni " + "on agg.id = uni.id").rewrite().getPlan();
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(0)));
    Assertions.assertFalse(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(1)));
    // roj propagate unique when left is unique
    plan = PlanChecker.from(connectContext).analyze("select agg.id, uni.id from agg right outer join uni " + "on agg.id = uni.name").rewrite().getPlan();
    Assertions.assertFalse(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(0)));
    Assertions.assertFalse(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(1)));
    plan = PlanChecker.from(connectContext).analyze("select agg.id, uni.id from agg right outer join uni " + "on agg.id = uni.id").rewrite().getPlan();
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(1)));
    Assertions.assertFalse(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(0)));
    // semi/anti join propagate all
    plan = PlanChecker.from(connectContext).analyze("select agg.id from agg left semi join uni " + "on agg.id = uni.name").rewrite().getPlan();
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(0)));
    plan = PlanChecker.from(connectContext).analyze("select agg.id from agg left anti join uni " + "on agg.id = uni.name").rewrite().getPlan();
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(0)));
    plan = PlanChecker.from(connectContext).analyze("select uni.id from agg right semi join uni " + "on agg.id = uni.name").rewrite().getPlan();
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(0)));
    plan = PlanChecker.from(connectContext).analyze("select uni.id from agg right anti join uni " + "on agg.id = uni.name").rewrite().getPlan();
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUnique(plan.getOutput().get(0)));
    // inner join propagate unique only when join key is unique
    plan = PlanChecker.from(connectContext).analyze("select uni.id, agg.id from agg inner join uni " + "on agg.id = uni.id").rewrite().getPlan();
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUniqueAndNotNull(plan.getOutput().get(0)));
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUniqueAndNotNull(plan.getOutput().get(1)));
    plan = PlanChecker.from(connectContext).analyze("select uni.id, agg.id from agg inner join uni " + "on agg.id = uni.name").rewrite().getPlan();
    Assertions.assertFalse(plan.getLogicalProperties().getTrait().isUnique(plan.getOutputSet()));
    plan = PlanChecker.from(connectContext).analyze("select uni.id, agg.id from agg inner join uni " + "on agg.id < uni.id").rewrite().getPlan();
    Assertions.assertFalse(plan.getLogicalProperties().getTrait().isUnique(plan.getOutputSet()));
    plan = PlanChecker.from(connectContext).analyze("select uni.id, agg.id from agg inner join uni " + "on agg.id = uni.id or agg.name > uni.name").rewrite().getPlan();
    Assertions.assertFalse(plan.getLogicalProperties().getTrait().isUnique(plan.getOutputSet()));
    plan = PlanChecker.from(connectContext).analyze("select uni.id, agg.id from agg inner join uni " + "on agg.id = uni.id and agg.name > uni.name").rewrite().getPlan();
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUniqueAndNotNull(plan.getOutput().get(0)));
    Assertions.assertTrue(plan.getLogicalProperties().getTrait().isUniqueAndNotNull(plan.getOutput().get(1)));
}

