    connectContext.getState().setIsQuery(true);
    PlanChecker.from(connectContext).checkPlannerResult("select * from db1.tagg", planner -> {
        List<Alias> collectedAlias = new ArrayList<>();
        planner.getCascadesContext().getRewritePlan().accept(new DefaultPlanVisitor<Void, List<Alias>>() {

            @Override
            public Void visitLogicalAggregate(LogicalAggregate<? extends Plan> aggregate, List<Alias> context) {
                for (Expression expression : aggregate.getExpressions()) {
                    collectedAlias.addAll(expression.collectToList(Alias.class::isInstance));
                }
                return super.visitLogicalAggregate(aggregate, context);
            }
        }, collectedAlias);
        for (Alias alias : collectedAlias) {
            for (Expression child : alias.children()) {
                Set<ExprId> childExpressionSet = child.collectToSet(NamedExpression.class::isInstance).stream().map(expr -> ((NamedExpression) expr).getExprId()).collect(Collectors.toSet());
                Assertions.assertFalse(childExpressionSet.contains(alias.getExprId()));
            }
        }
    });
}

