    LogicalUsingJoin<LogicalUsingJoin<LogicalSubQueryAlias<LogicalOlapScan>, LogicalSubQueryAlias<LogicalOlapScan>>, LogicalSubQueryAlias<LogicalOlapScan>> using2 = new LogicalUsingJoin<>(JoinType.LEFT_OUTER_JOIN, using1, sub3, ImmutableList.of(new UnboundSlot("id")), hint);
