@Test
void testTimestampDiff() {
    Expression result;
    UnboundFunction timeDiff;
    ImmutableList<String> functionNames = ImmutableList.of("timestampdiff", "datediff");
    for (String functionName : functionNames) {
        timeDiff = new UnboundFunction(functionName, ImmutableList.of(yearUnit, dateTimeV2Literal1, dateTimeV2Literal2));
        result = DatetimeFunctionBinder.INSTANCE.bind(timeDiff);
        Assertions.assertInstanceOf(YearsDiff.class, result);
        Assertions.assertEquals(dateTimeV2Literal2, result.child(0));
        Assertions.assertEquals(dateTimeV2Literal1, result.child(1));
        timeDiff = new UnboundFunction(functionName, ImmutableList.of(monthUnit, dateTimeV2Literal1, dateTimeV2Literal2));
        result = DatetimeFunctionBinder.INSTANCE.bind(timeDiff);
        Assertions.assertInstanceOf(MonthsDiff.class, result);
        Assertions.assertEquals(dateTimeV2Literal2, result.child(0));
        Assertions.assertEquals(dateTimeV2Literal1, result.child(1));
        timeDiff = new UnboundFunction(functionName, ImmutableList.of(weekUnit, dateTimeV2Literal1, dateTimeV2Literal2));
        result = DatetimeFunctionBinder.INSTANCE.bind(timeDiff);
        Assertions.assertInstanceOf(WeeksDiff.class, result);
        Assertions.assertEquals(dateTimeV2Literal2, result.child(0));
        Assertions.assertEquals(dateTimeV2Literal1, result.child(1));
        timeDiff = new UnboundFunction(functionName, ImmutableList.of(dayUnit, dateTimeV2Literal1, dateTimeV2Literal2));
        result = DatetimeFunctionBinder.INSTANCE.bind(timeDiff);
        Assertions.assertInstanceOf(DaysDiff.class, result);
        Assertions.assertEquals(dateTimeV2Literal2, result.child(0));
        Assertions.assertEquals(dateTimeV2Literal1, result.child(1));
        timeDiff = new UnboundFunction(functionName, ImmutableList.of(hourUnit, dateTimeV2Literal1, dateTimeV2Literal2));
        result = DatetimeFunctionBinder.INSTANCE.bind(timeDiff);
        Assertions.assertInstanceOf(HoursDiff.class, result);
        Assertions.assertEquals(dateTimeV2Literal2, result.child(0));
        Assertions.assertEquals(dateTimeV2Literal1, result.child(1));
        timeDiff = new UnboundFunction(functionName, ImmutableList.of(minuteUnit, dateTimeV2Literal1, dateTimeV2Literal2));
        result = DatetimeFunctionBinder.INSTANCE.bind(timeDiff);
        Assertions.assertInstanceOf(MinutesDiff.class, result);
        Assertions.assertEquals(dateTimeV2Literal2, result.child(0));
        Assertions.assertEquals(dateTimeV2Literal1, result.child(1));
        timeDiff = new UnboundFunction(functionName, ImmutableList.of(secondUnit, dateTimeV2Literal1, dateTimeV2Literal2));
        result = DatetimeFunctionBinder.INSTANCE.bind(timeDiff);
        Assertions.assertInstanceOf(SecondsDiff.class, result);
        Assertions.assertEquals(dateTimeV2Literal2, result.child(0));
        Assertions.assertEquals(dateTimeV2Literal1, result.child(1));
        Assertions.assertThrowsExactly(AnalysisException.class, () -> DatetimeFunctionBinder.INSTANCE.bind(new UnboundFunction(functionName, ImmutableList.of(invalidUnit, dateTimeV2Literal1, dateTimeV2Literal2))));
        timeDiff = new UnboundFunction(functionName, ImmutableList.of(quarterUnit, dateTimeV2Literal1, dateTimeV2Literal2));
        result = DatetimeFunctionBinder.INSTANCE.bind(timeDiff);
        Assertions.assertInstanceOf(QuartersDiff.class, result);
        Assertions.assertEquals(dateTimeV2Literal2, result.child(0));
        Assertions.assertEquals(dateTimeV2Literal1, result.child(1));
        if (functionName.equalsIgnoreCase("datediff")) {
            timeDiff = new UnboundFunction(functionName, ImmutableList.of(dateTimeV2Literal1, dateTimeV2Literal2));
            result = DatetimeFunctionBinder.INSTANCE.bind(timeDiff);
            Assertions.assertInstanceOf(DateDiff.class, result);
            Assertions.assertEquals(dateTimeV2Literal1, result.child(0));
            Assertions.assertEquals(dateTimeV2Literal2, result.child(1));
        } else {
            Assertions.assertThrowsExactly(AnalysisException.class, () -> DatetimeFunctionBinder.INSTANCE.bind(new UnboundFunction(functionName, ImmutableList.of(yearUnit, dateTimeV2Literal1))));
        }
        Assertions.assertThrowsExactly(AnalysisException.class, () -> DatetimeFunctionBinder.INSTANCE.bind(new UnboundFunction(functionName, ImmutableList.of(new UnboundSlot("unbound"), dateTimeV2Literal1, dateTimeV2Literal2))));
    }
}

