    "select * from (select sum(id) as k from t1) t", "select * from (select sum(id) as k from t1 where id > 10) t", // project sub query
    "select id, (select sum(t2.id) as k from t2) from t1", "select id, (select sum(t2.id) as k from t2 where t2.id > 10) from t1", "select id, (select sum(t2.id) as k from t2 where t1.id = t2.id) from t1", // filter sub query
