         * <p>
         *     t1.id=t3.id               t1.id=t2.id
         *       topJoin                  newTopJoin
         *       /     \                   /     \
         *    project   t3           project    project
         * t1.id=t2.id             t1.id=t3.id    t2
         * bottomJoin       -->   newBottomJoin
         *   /    \                   /    \
         * t1      t2               t1      t3
         */
    LogicalPlan plan = new LogicalPlanBuilder(scan1).join(scan2, JoinType.INNER_JOIN, Pair.of(0, 0)).project(ImmutableList.of(0, 1, 2)).join(scan3, JoinType.INNER_JOIN, Pair.of(1, 1)).projectAll().build();
