@Test
public void testJoinConjunctNullableWhenAssociate() {
    // t1 left outer join t2
    List<Expression> bottomHashJoinConjunct = ImmutableList.of(new EqualTo(scan1.getOutput().get(0), scan2.getOutput().get(0)));
    List<Expression> bottomOtherJoinConjunct = ImmutableList.of(new GreaterThan(scan1.getOutput().get(1), scan2.getOutput().get(1)));
    LogicalPlan bottomJoin = new LogicalPlanBuilder(scan1).join(scan2, JoinType.LEFT_OUTER_JOIN, bottomHashJoinConjunct, bottomOtherJoinConjunct).build();
    LogicalPlan bottomProject = new LogicalProject<>(bottomJoin.getOutput().stream().map(NamedExpression.class::cast).collect(Collectors.toList()), bottomJoin);
    // t2 left outer join t3
    List<Expression> topHashJoinConjunct = ImmutableList.of(new EqualTo(bottomProject.getOutput().get(2).withNullable(true), scan3.getOutput().get(0)));
    List<Expression> topOtherJoinConjunct = ImmutableList.of(new GreaterThan(bottomProject.getOutput().get(3).withNullable(true), scan3.getOutput().get(1)));
    LogicalPlan topJoin = new LogicalPlanBuilder(bottomProject).join(scan3, JoinType.LEFT_OUTER_JOIN, topHashJoinConjunct, topOtherJoinConjunct).build();
    LogicalPlan plan = new LogicalProject<>(topJoin.getOutput().stream().map(NamedExpression.class::cast).collect(Collectors.toList()), topJoin);
    List<Plan> allPlan = PlanChecker.from(MemoTestUtils.createConnectContext(), plan).printlnOrigin().applyExploration(OuterJoinAssocProject.INSTANCE.build()).getAllPlan();
    Assertions.assertEquals(2, allPlan.size());
    // check optimized join plan conjuncts null property, should be false
    Set<LogicalJoin<Plan, Plan>> joinSet = allPlan.get(1).collect(LogicalJoin.class::isInstance);
    for (LogicalJoin<Plan, Plan> newJoin : joinSet) {
        Plan child0 = newJoin.child(0);
        Plan child1 = newJoin.child(1);
        if ((child0 instanceof LogicalOlapScan && ((LogicalOlapScan) child0).getTable().getName().equals("t3")) || (child1 instanceof LogicalOlapScan && ((LogicalOlapScan) child1).getTable().getName().equals("t3"))) {
            // equal conjuncts nullable should be same with the join input slot
            for (Expression expr : newJoin.getHashJoinConjuncts()) {
                expr.collectToSet(SlotReference.class::isInstance).forEach(slot -> Assertions.assertFalse(((SlotReference) slot).nullable()));
            }
            // other conjuncts nullable should be same with the join output slot
            for (Expression expr : newJoin.getOtherJoinConjuncts()) {
                if (expr instanceof GreaterThan) {
                    Assertions.assertFalse(expr.child(0).nullable());
                    Assertions.assertTrue(expr.child(1).nullable());
                }
            }
        }
    }
}

