public void testGetQueryTableUsedPartition() {
    PlanChecker.from(connectContext).checkExplain("select l1.*, O_CUSTKEY \n" + "from lineitem_list_partition l1\n" + "left outer join orders_list_partition\n" + "on l1.l_shipdate = o_orderdate\n", nereidsPlanner -> {
        MaterializedViewUtils.collectTableUsedPartitions(nereidsPlanner.getRewrittenPlan(), nereidsPlanner.getCascadesContext());
        Map<List<String>, Set<String>> queryUsedPartitions = PartitionCompensator.getQueryUsedPartitions(nereidsPlanner.getCascadesContext().getStatementContext(), new BitSet());
        List<String> itmeQualifier = ImmutableList.of("internal", "partition_compensate_test", "lineitem_list_partition");
        Set<String> queryTableUsedPartition = queryUsedPartitions.get(itmeQualifier);
        Assertions.assertEquals(queryTableUsedPartition, ImmutableSet.of("p1", "p2", "p3"));
        List<String> orderQualifier = ImmutableList.of("internal", "partition_compensate_test", "orders_list_partition");
        Set<String> orderTableUsedPartition = queryUsedPartitions.get(orderQualifier);
        Assertions.assertEquals(orderTableUsedPartition, ImmutableSet.of("p1", "p2", "p3", "p4"));
    });
}

