@Test
void testSimplifyCastRule() {
    executor = new ExpressionRuleExecutor(ImmutableList.of(bottomUp(SimplifyCastRule.INSTANCE)));
    // deduplicate
    assertRewrite("CAST(1 AS tinyint)", "1");
    assertRewrite("CAST('str' AS varchar)", "'str'");
    assertRewrite("CAST(CAST(1 AS tinyint) AS tinyint)", "1");
    // deduplicate inside
    assertRewrite("CAST(CAST('str' AS varchar) AS double)", "CAST('str' AS double)");
    assertRewrite("CAST(CAST(1 AS tinyint) AS double)", "CAST(1 AS double)");
    // string literal
    assertRewrite(new Cast(new CharLiteral("123", 3), VarcharType.createVarcharType(10)), new VarcharLiteral("123", 10));
    assertRewrite(new Cast(new VarcharLiteral("123", 3), VarcharType.createVarcharType(10)), new VarcharLiteral("123", 10));
    assertRewrite(new Cast(new CharLiteral("123", 3), StringType.INSTANCE), new StringLiteral("123"));
    assertRewrite(new Cast(new VarcharLiteral("123", 3), StringType.INSTANCE), new StringLiteral("123"));
    // decimal literal
    assertRewrite(new Cast(new TinyIntLiteral((byte) 1), DecimalV2Type.createDecimalV2Type(15, 9)), new DecimalLiteral(DecimalV2Type.createDecimalV2Type(15, 9), new BigDecimal("1.000000000")));
    assertRewrite(new Cast(new SmallIntLiteral((short) 1), DecimalV2Type.createDecimalV2Type(15, 9)), new DecimalLiteral(DecimalV2Type.createDecimalV2Type(15, 9), new BigDecimal("1.000000000")));
    assertRewrite(new Cast(new IntegerLiteral(1), DecimalV2Type.createDecimalV2Type(15, 9)), new DecimalLiteral(DecimalV2Type.createDecimalV2Type(15, 9), new BigDecimal("1.000000000")));
    assertRewrite(new Cast(new BigIntLiteral(1L), DecimalV2Type.createDecimalV2Type(15, 9)), new DecimalLiteral(DecimalV2Type.createDecimalV2Type(15, 9), new BigDecimal("1.000000000")));
}

@Test
void testSimplifyDecimalV3Comparison() {
    executor = new ExpressionRuleExecutor(ImmutableList.of(bottomUp(SimplifyComparisonPredicate.INSTANCE)));
    // do rewrite
    Expression left = new DecimalV3Literal(new BigDecimal("12345.67"));
    Expression cast = new Cast(left, DecimalV3Type.createDecimalV3Type(27, 9));
    Expression right = new DecimalV3Literal(DecimalV3Type.createDecimalV3Type(27, 9), new BigDecimal("0.01"));
    Expression expectedRight = new DecimalV3Literal(DecimalV3Type.createDecimalV3Type(7, 2), new BigDecimal("0.01"));
    Expression comparison = new EqualTo(cast, right);
    Expression expected = new EqualTo(left, expectedRight);
    assertRewrite(comparison, expected);
