@Test
public void testExtractNonConstant() {
    String sql = "select * from T1 where id in (score, score, score + 100)";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalFilter().when(f -> f.getPredicate().toSql().equals("OR[(id = score),(id = (score + 100))]")));
    sql = "select * from T1 where id in (score,  score + 10, score + score, score, 10, 20, 30, 100 + 200)";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalFilter().when(f -> f.getPredicate().toSql().equals("OR[id IN (10, 20, 30, 300),(id = score),(id = (score + 10)),(id = (score + score))]")));
    // if IN predicate compareExpr contains unique function, don't extract it.
    sql = "select * from T1 where id + random(1, 10) in (score,  score + 10, score + score, score, 10, 20, 30, 100 + 200)";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalFilter().when(f -> f.getPredicate().toSql().equals("(id + random(1, 10)) IN ((score + 10), (score + score), 10, 20, 30, 300, score)")));
}

@Test
public void testSimplifyRangeAndExtractCommonFactor() {
    String sql = "select * from T1 where id > 1 and score > 1 or id > 1 and score > 10";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalFilter().when(f -> f.getPredicate().toSql().equals("AND[(id > 1),(score > 1)]")));
    sql = "select * from T1 where id > 1 and score > 1 or id > 1 and id < 0";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalFilter().when(f -> f.getPredicate().toSql().equals("AND[(score > 1),(id > 1)]")));
    sql = "select * from T1 where id > 1 and id < 0 or score > 1 and score < 0";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalEmptyRelation());
    sql = "select * from T1 where id > 1 and id < 0 and score > 1 and score < 0";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalEmptyRelation());
    sql = "select * from T1 where not(id > 1 and id < 0 or score > 1 and score < 0)";
    PlanChecker.from(connectContext).analyze(sql).rewrite().matches(logicalFilter().when(f -> f.getPredicate().toSql().equals("AND[( not id IS NULL),( not score IS NULL)]")));
}

