@Test
void testNestedCaseWhenReplacer() {
    // case when a > 1 then 101
    //      when a > 2 then (case when a > 1 then 102
    //                            when a > 2 then 103
    //                            when a > 3 then 104
    //                            when a > 4 then 105
    //                       else 106
    //                       end)
    //      when a > 3 then  107
    //      when a > 4 then  108
    //      when a > 4 then  109
    //      else 110
    // end
    SlotReference a = new SlotReference("a", IntegerType.INSTANCE);
    Expression c1 = new GreaterThan(a, IntegerLiteral.of(1));
    Expression c2 = new GreaterThan(a, IntegerLiteral.of(2));
    Expression c3 = new GreaterThan(a, IntegerLiteral.of(3));
    Expression c4 = new GreaterThan(a, IntegerLiteral.of(4));
    Expression i101 = IntegerLiteral.of(101);
    Expression i102 = IntegerLiteral.of(102);
    Expression i103 = IntegerLiteral.of(103);
    Expression i104 = IntegerLiteral.of(104);
    Expression i105 = IntegerLiteral.of(105);
    Expression i106 = IntegerLiteral.of(106);
    Expression i107 = IntegerLiteral.of(107);
    Expression i108 = IntegerLiteral.of(108);
    Expression i109 = IntegerLiteral.of(109);
    Expression i110 = IntegerLiteral.of(110);
    Expression innerCaseWhen = new CaseWhen(ImmutableList.of(new WhenClause(c1, i102), new WhenClause(c2, i103), new WhenClause(c3, i104), new WhenClause(c4, i105)), i106);
    Expression outerCaseWhen = new CaseWhen(ImmutableList.of(new WhenClause(c1, i101), new WhenClause(c2, innerCaseWhen), new WhenClause(c3, i107), new WhenClause(c4, i108), new WhenClause(c4, i109)), i110);
    TestNestedCondReplacer replacer = new TestNestedCondReplacer();
    outerCaseWhen.accept(replacer, null);
    replacer.checkExpressionReplaceLiterals(outerCaseWhen, ImmutableList.of(), ImmutableList.of());
    replacer.checkExpressionReplaceLiterals(i101, ImmutableList.of(c1), ImmutableList.of());
    replacer.checkExpressionReplaceLiterals(i102, ImmutableList.of(c2), ImmutableList.of(c1));
    replacer.checkExpressionReplaceLiterals(i103, ImmutableList.of(c2), ImmutableList.of(c1));
    replacer.checkExpressionReplaceLiterals(i104, ImmutableList.of(c2, c3), ImmutableList.of(c1));
    replacer.checkExpressionReplaceLiterals(i105, ImmutableList.of(c2, c4), ImmutableList.of(c1, c3));
    replacer.checkExpressionReplaceLiterals(i106, ImmutableList.of(c2), ImmutableList.of(c1, c3, c4));
    replacer.checkExpressionReplaceLiterals(i107, ImmutableList.of(c3), ImmutableList.of(c1, c2));
    replacer.checkExpressionReplaceLiterals(i108, ImmutableList.of(c4), ImmutableList.of(c1, c2, c3));
    replacer.checkExpressionReplaceLiterals(i109, ImmutableList.of(), ImmutableList.of(c1, c2, c3, c4));
    replacer.checkExpressionReplaceLiterals(i110, ImmutableList.of(), ImmutableList.of(c1, c2, c3, c4));
    // after rewrite, the condition literals should clear
    Assertions.assertEquals(Maps.newHashMap(), replacer.conditionLiterals);
}

@Test
void testNestedIfReplacer() {
    // if(a > 1,
    //      if(a > 2,
    //              if(a > 3, 301, 302),
    //              if(a > 4, 303, 304)
    //         ),
    //      if(a > 5, 305, 306)
    // )
    SlotReference a = new SlotReference("a", IntegerType.INSTANCE);
    Expression c1 = new GreaterThan(a, IntegerLiteral.of(1));
    Expression c2 = new GreaterThan(a, IntegerLiteral.of(2));
    Expression c3 = new GreaterThan(a, IntegerLiteral.of(3));
    Expression c4 = new GreaterThan(a, IntegerLiteral.of(4));
    Expression c5 = new GreaterThan(a, IntegerLiteral.of(5));
    Expression i301 = IntegerLiteral.of(301);
    Expression i302 = IntegerLiteral.of(302);
    Expression i303 = IntegerLiteral.of(303);
    Expression i304 = IntegerLiteral.of(304);
    Expression i305 = IntegerLiteral.of(305);
    Expression i306 = IntegerLiteral.of(306);
    Expression innerIf1 = new If(c3, i301, i302);
    Expression innerIf2 = new If(c4, i303, i304);
    Expression innerIf = new If(c2, innerIf1, innerIf2);
    Expression outerIf = new If(c1, innerIf, new If(c5, i305, i306));
    TestNestedCondReplacer replacer = new TestNestedCondReplacer();
    outerIf.accept(replacer, null);
    replacer.checkExpressionReplaceLiterals(outerIf, ImmutableList.of(), ImmutableList.of());
    replacer.checkExpressionReplaceLiterals(innerIf, ImmutableList.of(c1), ImmutableList.of());
    replacer.checkExpressionReplaceLiterals(innerIf1, ImmutableList.of(c1, c2), ImmutableList.of());
    replacer.checkExpressionReplaceLiterals(i301, ImmutableList.of(c1, c2, c3), ImmutableList.of());
    replacer.checkExpressionReplaceLiterals(i302, ImmutableList.of(c1, c2), ImmutableList.of(c3));
    replacer.checkExpressionReplaceLiterals(innerIf2, ImmutableList.of(c1), ImmutableList.of(c2));
