@Test
void testRound() {
    executor = new ExpressionRuleExecutor(ImmutableList.of(bottomUp(SimplifyCastRule.INSTANCE, SimplifyComparisonPredicate.INSTANCE)));
    Expression left = new Cast(new DateTimeLiteral("2021-01-02 00:00:00.00"), DateTimeV2Type.of(1));
    Expression right = new DateTimeV2Literal("2021-01-01 23:59:59.99");
    // (cast(2021-01-02 00:00:00.00 as DATETIMEV2(1)) > 2021-01-01 23:59:59.99)
    Expression expression = new GreaterThan(left, right);
    Expression rewrittenExpression = executor.rewrite(typeCoercion(expression), context);
    // right should round to be 2021-01-01 23:59:59
    Assertions.assertEquals(new DateTimeLiteral("2021-01-01 23:59:59"), rewrittenExpression.child(1));
}

@Test
void testDoubleLiteral() {
    executor = new ExpressionRuleExecutor(ImmutableList.of(bottomUp(SimplifyComparisonPredicate.INSTANCE)));
    Expression leftChild = new BigIntLiteral(999);
    Expression left = new Cast(leftChild, DoubleType.INSTANCE);
    Expression right = new DoubleLiteral(111);
    Expression expression = new GreaterThanEqual(left, right);
    Expression rewrittenExpression = executor.rewrite(expression, context);
    Assertions.assertEquals(left.child(0).getDataType(), rewrittenExpression.child(1).getDataType());
    Assertions.assertEquals(rewrittenExpression.child(0).getDataType(), rewrittenExpression.child(1).getDataType());
    Expression tinyIntSlot = new SlotReference("a", TinyIntType.INSTANCE);
    Expression smallIntSlot = new SlotReference("a", SmallIntType.INSTANCE);
    Expression intSlot = new SlotReference("a", IntegerType.INSTANCE);
    Expression bigIntSlot = new SlotReference("a", BigIntType.INSTANCE);
    // tiny int, literal not exceeds data type limit
    assertRewrite(new EqualTo(new Cast(tinyIntSlot, FloatType.INSTANCE), new FloatLiteral(12.0f)), new EqualTo(tinyIntSlot, new TinyIntLiteral((byte) 12)));
    assertRewrite(new EqualTo(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.0f)), new EqualTo(tinyIntSlot, new TinyIntLiteral((byte) 12)));
    assertRewrite(new EqualTo(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new NullSafeEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), BooleanLiteral.FALSE);
    assertRewrite(new GreaterThan(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThan(tinyIntSlot, new TinyIntLiteral((byte) 12)));
    assertRewrite(new GreaterThanEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThanEqual(tinyIntSlot, new TinyIntLiteral((byte) 13)));
    assertRewrite(new LessThan(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThan(tinyIntSlot, new TinyIntLiteral((byte) 13)));
    assertRewrite(new LessThanEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThanEqual(tinyIntSlot, new TinyIntLiteral((byte) 12)));
    // tiny int, literal exceeds data type limit
    assertRewrite(new EqualTo(new Cast(tinyIntSlot, FloatType.INSTANCE), new FloatLiteral(200.0f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new EqualTo(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.0f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new EqualTo(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new NullSafeEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), BooleanLiteral.FALSE);
    assertRewrite(new GreaterThan(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new GreaterThanEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.falseOrNull(tinyIntSlot));
    assertRewrite(new LessThan(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.trueOrNull(tinyIntSlot));
    assertRewrite(new LessThanEqual(new Cast(tinyIntSlot, DoubleType.INSTANCE), new DoubleLiteral(200.3f)), ExpressionUtils.trueOrNull(tinyIntSlot));
    // small int
    assertRewrite(new EqualTo(new Cast(smallIntSlot, FloatType.INSTANCE), new FloatLiteral(12.0f)), new EqualTo(smallIntSlot, new SmallIntLiteral((short) 12)));
    assertRewrite(new EqualTo(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.0f)), new EqualTo(smallIntSlot, new SmallIntLiteral((short) 12)));
    assertRewrite(new EqualTo(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), ExpressionUtils.falseOrNull(smallIntSlot));
    assertRewrite(new NullSafeEqual(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), BooleanLiteral.FALSE);
    assertRewrite(new GreaterThan(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThan(smallIntSlot, new SmallIntLiteral((short) 12)));
    assertRewrite(new GreaterThanEqual(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThanEqual(smallIntSlot, new SmallIntLiteral((short) 13)));
    assertRewrite(new LessThan(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThan(smallIntSlot, new SmallIntLiteral((short) 13)));
    assertRewrite(new LessThanEqual(new Cast(smallIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThanEqual(smallIntSlot, new SmallIntLiteral((short) 12)));
    // int
    assertRewrite(new EqualTo(new Cast(intSlot, FloatType.INSTANCE), new FloatLiteral(12.0f)), new EqualTo(intSlot, new IntegerLiteral(12)));
    assertRewrite(new EqualTo(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.0f)), new EqualTo(intSlot, new IntegerLiteral(12)));
    assertRewrite(new EqualTo(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), ExpressionUtils.falseOrNull(intSlot));
    assertRewrite(new NullSafeEqual(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), BooleanLiteral.FALSE);
    assertRewrite(new GreaterThan(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThan(intSlot, new IntegerLiteral(12)));
    assertRewrite(new GreaterThanEqual(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThanEqual(intSlot, new IntegerLiteral(13)));
    assertRewrite(new LessThan(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThan(intSlot, new IntegerLiteral(13)));
    assertRewrite(new LessThanEqual(new Cast(intSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThanEqual(intSlot, new IntegerLiteral(12)));
    // big int
    assertRewrite(new EqualTo(new Cast(bigIntSlot, FloatType.INSTANCE), new FloatLiteral(12.0f)), new EqualTo(bigIntSlot, new BigIntLiteral(12L)));
    assertRewrite(new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.0f)), new EqualTo(bigIntSlot, new BigIntLiteral(12L)));
    assertRewrite(new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), ExpressionUtils.falseOrNull(bigIntSlot));
    assertRewrite(new NullSafeEqual(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), BooleanLiteral.FALSE);
    assertRewrite(new GreaterThan(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThan(bigIntSlot, new BigIntLiteral(12L)));
    assertRewrite(new GreaterThanEqual(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new GreaterThanEqual(bigIntSlot, new BigIntLiteral(13L)));
    assertRewrite(new LessThan(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThan(bigIntSlot, new BigIntLiteral(13L)));
    assertRewrite(new LessThanEqual(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(12.3f)), new LessThanEqual(bigIntSlot, new BigIntLiteral(12L)));
    // int and float literal near no loss bound
    // 2^24
    float noLossBoundF = 16777216.0f;
    assertRewrite(new EqualTo(new Cast(intSlot, FloatType.INSTANCE), new FloatLiteral(-noLossBoundF)), new EqualTo(new Cast(intSlot, FloatType.INSTANCE), new FloatLiteral(-noLossBoundF)));
    assertRewrite(new EqualTo(new Cast(intSlot, FloatType.INSTANCE), new FloatLiteral(-16777215.0f)), new EqualTo(intSlot, new IntegerLiteral(-16777215)));
    assertRewrite(new EqualTo(new Cast(intSlot, FloatType.INSTANCE), new FloatLiteral(16777215.0f)), new EqualTo(intSlot, new IntegerLiteral(16777215)));
    assertRewrite(new EqualTo(new Cast(intSlot, FloatType.INSTANCE), new FloatLiteral(noLossBoundF)), new EqualTo(new Cast(intSlot, FloatType.INSTANCE), new FloatLiteral(noLossBoundF)));
    // big int and double literal near no loss bound
    double noLossBoundD = 9007199254740992.0;
    assertRewrite(new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(-noLossBoundD)), new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(-noLossBoundD)));
    assertRewrite(new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(-9007199254740991.0)), new EqualTo(bigIntSlot, new BigIntLiteral(-9007199254740991L)));
    assertRewrite(new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(9007199254740991.0)), new EqualTo(bigIntSlot, new BigIntLiteral(9007199254740991L)));
    assertRewrite(new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(noLossBoundD)), new EqualTo(new Cast(bigIntSlot, DoubleType.INSTANCE), new DoubleLiteral(noLossBoundD)));
}

