@Test
void testEliminateSortUnderTableSink() {
    // topN under table sink should not be removed
    LogicalOlapScan scan = PlanConstructor.newLogicalOlapScan(0, "t1", 0);
    LogicalPlan plan = new LogicalPlanBuilder(scan).sort(scan.getOutput().stream().map(c -> new OrderKey(c, true, true)).collect(Collectors.toList())).limit(1, 1).build();
    plan = new LogicalOlapTableSink<>(new Database(), scan.getTable(), scan.getTable().getBaseSchema(), new ArrayList<>(), plan.getOutput().stream().map(NamedExpression.class::cast).collect(Collectors.toList()), false, TPartialUpdateNewRowPolicy.APPEND, DMLCommandType.NONE, plan);
    PlanChecker.from(MemoTestUtils.createConnectContext(), plan).disableNereidsRules("PRUNE_EMPTY_PARTITION").rewrite().nonMatch(logicalSort()).matches(logicalTopN());
    // sort under table sink should be removed
    scan = PlanConstructor.newLogicalOlapScan(0, "t2", 0);
    plan = new LogicalPlanBuilder(scan).sort(scan.getOutput().stream().map(c -> new OrderKey(c, true, true)).collect(Collectors.toList())).build();
    plan = new LogicalOlapTableSink<>(new Database(), scan.getTable(), scan.getTable().getBaseSchema(), new ArrayList<>(), plan.getOutput().stream().map(NamedExpression.class::cast).collect(Collectors.toList()), false, TPartialUpdateNewRowPolicy.APPEND, DMLCommandType.NONE, plan);
    PlanChecker.from(MemoTestUtils.createConnectContext(), plan).rewrite().nonMatch(logicalSort());
}

