    PlanChecker.from(new ConnectContext(), join).applyTopDown(new FindHashConditionForJoin()).matches(logicalJoin().when(j -> j.getHashJoinConjuncts().equals(ImmutableList.of(eq1, eq3, eq4))).when(j -> j.getOtherJoinConjuncts().equals(ImmutableList.of(eq2, or, less, eq5))));
