@Test
void notPushDownFilterThroughNonfoldable() {
    ConnectContext context = MemoTestUtils.createConnectContext();
    Alias foldableAlias = new Alias(new ExprId(1), scan.getOutput().get(0), "a");
    Alias nonfoldableAlias = new Alias(new ExprId(2), new Random(new BigIntLiteral(1L), new BigIntLiteral(10L)), "b");
    Expression nonfoldableAdd = new Add(foldableAlias.toSlot(), new Random(new BigIntLiteral(1L), new BigIntLiteral(2L)));
    Expression condition = new And(Lists.newArrayList(new IsNull(foldableAlias.toSlot()), new IsNull(nonfoldableAlias.toSlot()), new IsNull(nonfoldableAdd)));
    LogicalPlan plan = new LogicalPlanBuilder(scan).projectExprs(ImmutableList.of(foldableAlias, nonfoldableAlias)).filter(condition).build();
    PlanChecker.from(context, plan).applyTopDown(new PushDownFilterThroughProject()).matches(logicalFilter(logicalProject(logicalFilter().when(f -> f.getPredicate().toSql().equals("AND[id IS NULL,(id + random(1, 2)) IS NULL]")))).when(f -> f.getPredicate().toSql().equals("b IS NULL")));
    plan = new LogicalPlanBuilder(scan).projectExprs(ImmutableList.of(foldableAlias, nonfoldableAlias)).limit(1).filter(condition).build();
    PlanChecker.from(context, plan).applyTopDown(new PushDownFilterThroughProject()).matches(logicalFilter(logicalProject(logicalFilter(logicalLimit()).when(f -> f.getPredicate().toSql().equals("AND[id IS NULL,(id + random(1, 2)) IS NULL]")))).when(f -> f.getPredicate().toSql().equals("b IS NULL")));
}

