/**
 * verify that after applying PushDownAggThroughJoin rule, agg func has correct dataType
 */
@Test
void testSumAndDataType() {
    LogicalOlapScan salary1 = new LogicalOlapScan(PlanConstructor.getNextRelationId(), PlanConstructor.salary, ImmutableList.of(""));
    Alias sum = new Sum(salary1.getOutput().get(2)).alias("sum");
    LogicalPlan plan = new LogicalPlanBuilder(salary1).join(scan2, JoinType.INNER_JOIN, Pair.of(0, 0)).aggGroupUsingIndex(ImmutableList.of(0), ImmutableList.of(salary1.getOutput().get(0), sum)).build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), plan).applyTopDown(new PushDownAggThroughJoin()).matches(logicalAggregate(logicalJoin(logicalAggregate(), logicalAggregate())).when(agg -> {
        Multiply multiply = null;
        for (Expression expr : agg.getOutputExpressions()) {
            if (expr instanceof Alias && expr.child(0) instanceof Sum && expr.child(0).child(0) instanceof Multiply) {
                multiply = (Multiply) expr.child(0).child(0);
                break;
            }
        }
        if (multiply == null) {
            return false;
        }
        Assertions.assertInstanceOf(DecimalV3Type.class, multiply.child(0).getDataType());
        Assertions.assertInstanceOf(DecimalV3Type.class, multiply.child(1).getDataType());
        return true;
    }));
}

