@Test
public void testPushDownMarkConjuncts() {
    Plan left = new LogicalOneRowRelation(new RelationId(1), ImmutableList.of(new Alias(new ExprId(1), new IntegerLiteral(1), "a")));
    Plan right = new LogicalOneRowRelation(new RelationId(2), ImmutableList.of(new Alias(new ExprId(2), new IntegerLiteral(2), "b")));
    Expression sameLeft = new Abs(left.getOutput().get(0));
    Expression sameRight = new Positive(right.getOutput().get(0));
    Expression hashLeft = new Cast(sameLeft, StringType.INSTANCE);
    Expression hashRight = new Cast(sameRight, StringType.INSTANCE);
    Expression markLeft = new Cast(sameLeft, BigIntType.INSTANCE);
    Expression markRight = new Cast(sameRight, BigIntType.INSTANCE);
    LogicalJoin<?, ?> plan = new LogicalJoin<>(JoinType.INNER_JOIN, left, right, new JoinReorderContext());
    Expression sameConjuncts = new EqualTo(sameLeft, sameRight);
    Expression hashConjuncts = new EqualTo(hashLeft, hashRight);
    Expression markConjuncts = new EqualTo(markLeft, markRight);
    Expression otherConjuncts = new Add(left.getOutput().get(0), new IntegerLiteral(1));
    plan = plan.withJoinConjuncts(ImmutableList.of(sameConjuncts, hashConjuncts), ImmutableList.of(otherConjuncts), ImmutableList.of(sameConjuncts, markConjuncts, otherConjuncts), new JoinReorderContext());
    PlanChecker.from(connectContext, plan).applyTopDown(new PushDownExpressionsInHashCondition()).matches(logicalJoin(logicalProject(logicalOneRowRelation()).when(p -> p.getProjects().size() == 4 && p.getProjects().stream().filter(Alias.class::isInstance).map(Alias.class::cast).map(UnaryNode::child).filter(sameLeft::equals).count() == 1 && p.getProjects().stream().filter(Alias.class::isInstance).map(Alias.class::cast).map(UnaryNode::child).filter(markLeft::equals).count() == 1 && p.getProjects().stream().filter(Alias.class::isInstance).map(Alias.class::cast).map(UnaryNode::child).filter(hashLeft::equals).count() == 1), logicalProject(logicalOneRowRelation()).when(p -> p.getProjects().size() == 4 && p.getProjects().stream().filter(Alias.class::isInstance).map(Alias.class::cast).map(UnaryNode::child).filter(sameRight::equals).count() == 1 && p.getProjects().stream().filter(Alias.class::isInstance).map(Alias.class::cast).map(UnaryNode::child).filter(markRight::equals).count() == 1 && p.getProjects().stream().filter(Alias.class::isInstance).map(Alias.class::cast).map(UnaryNode::child).filter(hashRight::equals).count() == 1)).when(j -> j.getMarkJoinConjuncts().size() == 3 && j.getMarkJoinConjuncts().stream().filter(EqualTo.class::isInstance).allMatch(e -> ((EqualTo) e).left() instanceof SlotReference && ((EqualTo) e).right() instanceof SlotReference) && j.getMarkJoinConjuncts().stream().filter(EqualTo.class::isInstance).count() == 2).when(j -> j.getHashJoinConjuncts().size() == 2 && j.getHashJoinConjuncts().stream().filter(EqualTo.class::isInstance).allMatch(e -> ((EqualTo) e).left() instanceof SlotReference && ((EqualTo) e).right() instanceof SlotReference) && j.getHashJoinConjuncts().stream().filter(EqualTo.class::isInstance).count() == 2));
}

