    LogicalPlan plan = new LogicalPlanBuilder(leftJoin).joinEmptyOn(rightJoin, JoinType.CROSS_JOIN).filter(new EqualTo(scan1.getOutput().get(0), scan3.getOutput().get(0))).build();
