@Test
public void testStringRangeColToCol() {
    SlotReference a = new SlotReference("a", new VarcharType(25));
    ColumnStatisticBuilder columnStatisticBuilderA = new ColumnStatisticBuilder(100).setNdv(100).setAvgSizeByte(25).setNumNulls(0).setMaxExpr(new StringLiteral("2022-01-01").toLegacyLiteral()).setMaxValue(new VarcharLiteral("2022-01-01").getDouble()).setMinExpr(new StringLiteral("2020-01-01").toLegacyLiteral()).setMinValue(new VarcharLiteral("2020-01-01").getDouble());
    SlotReference b = new SlotReference("b", new VarcharType(25));
    ColumnStatisticBuilder columnStatisticBuilderB = new ColumnStatisticBuilder(100).setNdv(100).setAvgSizeByte(25).setNumNulls(0).setMaxExpr(new StringLiteral("2012-01-01").toLegacyLiteral()).setMaxValue(new VarcharLiteral("2012-01-01").getDouble()).setMinExpr(new StringLiteral("2010-01-01").toLegacyLiteral()).setMinValue(new VarcharLiteral("2010-01-01").getDouble());
    SlotReference c = new SlotReference("c", new VarcharType(25));
    ColumnStatisticBuilder columnStatisticBuilderC = new ColumnStatisticBuilder(100).setNdv(100).setAvgSizeByte(25).setNumNulls(0).setMaxExpr(new StringLiteral("2021-01-01").toLegacyLiteral()).setMaxValue(new VarcharLiteral("2021-01-01").getDouble()).setMinExpr(new StringLiteral("2010-01-01").toLegacyLiteral()).setMinValue(new VarcharLiteral("2010-01-01").getDouble());
    StatisticsBuilder statsBuilder = new StatisticsBuilder();
    statsBuilder.setRowCount(100);
    statsBuilder.putColumnStatistics(a, columnStatisticBuilderA.build());
    statsBuilder.putColumnStatistics(b, columnStatisticBuilderB.build());
    statsBuilder.putColumnStatistics(c, columnStatisticBuilderC.build());
    Statistics baseStats = statsBuilder.build();
    // (2020-2022) > (2010,2012), sel=1
    // string type, use conservative way to do estimation: sel = DEFAULT (0.5)
    Statistics agrtb = new FilterEstimation().estimate(new GreaterThan(a, b), baseStats);
    Assertions.assertEquals(50, agrtb.getRowCount());
    // (2020-2022) < (2010,2012), sel=0
    // string type, use conservative way to do estimation: sel = DEFAULT (0.5)
    Statistics alessb = new FilterEstimation().estimate(new LessThan(a, b), baseStats);
    Assertions.assertEquals(50, alessb.getRowCount());
    // (2020-2022) > (2010-2021), sel = DEFAULT (0.5)
    Statistics agrtc = new FilterEstimation().estimate(new GreaterThan(a, c), baseStats);
    Assertions.assertEquals(50, agrtc.getRowCount());
}

