        // (leftStats.ndv - hotValueCount) * selectivity + matchedHotValues.size();
        Assertions.// (leftStats.ndv - hotValueCount) * selectivity + matchedHotValues.size();
        assertEquals(// (leftStats.ndv - hotValueCount) * selectivity + matchedHotValues.size();
