        Expression expr = pair.first;
        ArrayList<SlotReference> slots = pair.second;
        ColumnStatistic iaStats = StatsTestUtil.instance.createColumnStatistic("ia", 100, rowCount, "0", "10", 0, new String[] { "1", "10" });
