@Test
public void testConstantExpression() {
    // literal is constant
    Assertions.assertTrue(new StringLiteral("abc").isConstant());
    // slot reference is not constant
    Assertions.assertFalse(new SlotReference("a", IntegerType.INSTANCE).isConstant());
    // `1 + 2` is constant
    Assertions.assertTrue(new Add(new IntegerLiteral(1), new IntegerLiteral(2)).isConstant());
    // `a + 1` is not constant
    Assertions.assertFalse(new Add(new SlotReference("a", IntegerType.INSTANCE), new IntegerLiteral(1)).isConstant());
}

@Test
public void testContainsNondeterministic() {
    Assertions.assertTrue(new DaysAdd(new CurrentDate(), new IntegerLiteral(2)).containsNondeterministic());
    Assertions.assertTrue(new DaysAdd(new UnixTimestamp(new CurrentDate(), new VarcharLiteral("%Y-%m-%d %H:%i-%s")), new IntegerLiteral(2)).containsNondeterministic());
    Assertions.assertTrue(new DaysAdd(new UnixTimestamp(new CurrentDate()), new IntegerLiteral(2)).containsNondeterministic());
    Assertions.assertFalse(new DaysAdd(new UnixTimestamp(new DateLiteral("2024-01-01"), new VarcharLiteral("%Y-%m-%d %H:%i-%s")), new IntegerLiteral(2)).containsNondeterministic());
    Assertions.assertTrue(new DaysAdd(new UnixTimestamp(), new IntegerLiteral(2)).containsNondeterministic());
}

