@Test
void testComplexNestedMixedTimePrecisionPromotion() {
    // Create a complex nested structure with both DateTimeV2 and TimeV2 types
    FunctionSignature signature = FunctionSignature.ret(MapType.of(DateTimeV2Type.SYSTEM_DEFAULT, ArrayType.of(TimeV2Type.INSTANCE))).args(MapType.of(DateTimeV2Type.SYSTEM_DEFAULT, ArrayType.of(TimeV2Type.INSTANCE)), ArrayType.of(MapType.of(TimeV2Type.INSTANCE, DateTimeV2Type.SYSTEM_DEFAULT)), DateTimeV2Type.SYSTEM_DEFAULT);
    Map<Literal, Literal> map = Maps.newLinkedHashMap();
    map.put(new DateTimeV2Literal("2020-02-02 00:00:00.12"), new ArrayLiteral(Lists.newArrayList(new TimeV2Literal("12:34:56.1"))));
    Map<Literal, Literal> map2 = Maps.newLinkedHashMap();
    map2.put(new TimeV2Literal("12:34:56.123"), new DateTimeV2Literal("2020-02-02 00:00:00"));
    // Create complex arguments with different precisions
    List<Expression> arguments = Lists.newArrayList(// Map(DateTimeV2(2) -> Array(TimeV2(1)))
    new MapLiteral(map), // Array(Map(TimeV2(3) -> DateTimeV2(0)))
    new ArrayLiteral(Lists.newArrayList(new MapLiteral(map2))), // DateTimeV2(4)
    new DateTimeV2Literal("2020-02-02 00:00:00.1234"));
    signature = ComputeSignatureHelper.computePrecision(new FakeComputeSignature(), signature, arguments);
    // All time types should be promoted to precision 4
    // Check first argument: Map(DateTimeV2 -> Array(TimeV2))
    Assertions.assertTrue(signature.getArgType(0) instanceof MapType);
    Assertions.assertEquals(DateTimeV2Type.of(4), ((MapType) signature.getArgType(0)).getKeyType());
    Assertions.assertTrue(((MapType) signature.getArgType(0)).getValueType() instanceof ArrayType);
    Assertions.assertEquals(TimeV2Type.of(4), ((ArrayType) ((MapType) signature.getArgType(0)).getValueType()).getItemType());
    // Check second argument: Array(Map(TimeV2 -> DateTimeV2))
    Assertions.assertTrue(signature.getArgType(1) instanceof ArrayType);
    Assertions.assertTrue(((ArrayType) signature.getArgType(1)).getItemType() instanceof MapType);
    Assertions.assertEquals(TimeV2Type.of(4), ((MapType) ((ArrayType) signature.getArgType(1)).getItemType()).getKeyType());
    Assertions.assertEquals(DateTimeV2Type.of(4), ((MapType) ((ArrayType) signature.getArgType(1)).getItemType()).getValueType());
    // Check third argument: DateTimeV2
    Assertions.assertEquals(DateTimeV2Type.of(4), signature.getArgType(2));
    // Check return type: Map(DateTimeV2 -> Array(TimeV2))
    Assertions.assertTrue(signature.returnType instanceof MapType);
    Assertions.assertEquals(DateTimeV2Type.of(4), ((MapType) signature.returnType).getKeyType());
    Assertions.assertTrue(((MapType) signature.returnType).getValueType() instanceof ArrayType);
    Assertions.assertEquals(TimeV2Type.of(4), ((ArrayType) ((MapType) signature.returnType).getValueType()).getItemType());
}

