@Test
void testAggregateWithGroupBy5() {
    // all the 'a + random()' equals,  all the 'a + random() + 1' equals
    String sql = "select a + random(), a + random() + 1, a + random() + 2, " + " sum(a + random()), sum(a + random() + 1), sum(a + random() + 2), " + " sum(a + random()) over(), " + " sum(a + random() + 1) over(), " + " sum(a + random() + 2) over()" + " from t" + " where a + random() > 1 and a + random() + 1 > 1 and a + random() + 2 > 1" + " group by a + random(), a + random() + 1" + " having a + random() > 10 and a + random() + 1 > 20 and a + random() + 1 > 30" + " qualify max(a + random()) over() > 10 and max(a + random() + 1) over() > 20";
    Plan root = PlanChecker.from(connectContext).analyze(sql).rewrite().getPlan();
    Map<ExprId, Expression> exprIdToOriginExprMap = getExprIdToOriginExpressionMap(root);
    // validate 'a + random()' equal
