@Test
public void testComplex() throws Exception {
    // array type
    checkCompareSameType(0, new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200))), new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200))));
    checkCompareSameType(1, new ArrayLiteral(ImmutableList.of(new IntegerLiteral(200))), new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200))));
    checkCompareSameType(1, new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200), new IntegerLiteral(1))), new ArrayLiteral(ImmutableList.of(new IntegerLiteral(100), new IntegerLiteral(200))));
    checkComparableNoException("select array(1,2) = array(1, 2)");
    checkComparableNoException("select array(1,2) > array(1, 2)");
    // json type
    checkNotComparable("select cast ('[1, 2]' as json) = cast('[1, 2]' as json)", "comparison predicate could not contains json type");
    checkNotComparable("select cast('[1, 2]' as json) > cast('[1, 2]' as json)", "comparison predicate could not contains json type");
    // map type
    checkNotComparable("select map(1, 2) = map(1, 2)", "comparison predicate could not contains complex type");
    checkNotComparable("select map(1, 2) > map(1, 2)", "comparison predicate could not contains complex type");
    checkNotComparable("select cast('(1, 2)' as map<int, int>) = cast('(1, 2)' as map<int, int>)", "comparison predicate could not contains complex type");
    // struct type
    checkNotComparable("select struct(1, 2) = struct(1, 2)", "comparison predicate could not contains complex type");
    checkNotComparable("select struct(1, 2) > struct(1, 2)", "comparison predicate could not contains complex type");
}

@Test
void reject() {
    Assertions.assertThrows(AnalysisException.class, () -> new DateLiteral("2022-01-01 01:00:00.000000"));
    Assertions.assertThrows(AnalysisException.class, () -> new DateLiteral("2022-01-01 00:01:00.000000"));
    Assertions.assertThrows(AnalysisException.class, () -> new DateLiteral("2022-01-01 00:00:01.000000"));
    Assertions.assertThrows(AnalysisException.class, () -> new DateLiteral("2022-01-01 00:00:00.000001"));
}

@Test
void testNormalize() {
    String s = DateLiteral.normalize("2021-5").get();
    Assertions.assertEquals("2021-05", s);
    s = DateLiteral.normalize("2021-5-1").get();
    Assertions.assertEquals("2021-05-01", s);
    s = DateLiteral.normalize("2021-5-01").get();
    Assertions.assertEquals("2021-05-01", s);
    s = DateLiteral.normalize("2021-5-01 0:0:0").get();
    Assertions.assertEquals("2021-05-01 00:00:00", s);
    s = DateLiteral.normalize("2021-5-01 0:0:0.001").get();
    Assertions.assertEquals("2021-05-01 00:00:00.001", s);
    s = DateLiteral.normalize("2021-5-01 0:0:0.12345678").get();
    Assertions.assertEquals("2021-05-01 00:00:00.1234567", s);
    s = DateLiteral.normalize("2021-5-1    Asia/Shanghai").get();
    Assertions.assertEquals("2021-05-01Asia/Shanghai", s);
    s = DateLiteral.normalize("2021-5-1 0:0:0.12345678   Asia/Shanghai").get();
    Assertions.assertEquals("2021-05-01 00:00:00.1234567Asia/Shanghai", s);
}

