    Assertions.assertInstanceOf(DoubleLiteral.class, expression);
    Assertions.assertEquals(Float.POSITIVE_INFINITY, ((DoubleLiteral) expression).getValue().doubleValue());
    s = new StringLiteral("-InfiNIty");
