    Assertions.assertThrows(ParseException.class, () -> PlanChecker.from(MemoTestUtils.createConnectContext()).checkParse(sql3, (checker) -> checker.matches(logicalProject(logicalCheckPolicy(unboundRelation())))));
    // no replace expression
    String sql4 = "select * replace() from t1";
    Assertions.assertThrows(ParseException.class, () -> PlanChecker.from(MemoTestUtils.createConnectContext()).checkParse(sql4, (checker) -> checker.matches(logicalProject(logicalCheckPolicy(logicalOneRowRelation())))));
    // no from clause
    String sql5 = "select * replace('new' as v1)";
    Assertions.assertThrows(ParseException.class, () -> PlanChecker.from(MemoTestUtils.createConnectContext()).checkParse(sql5, (checker) -> checker.matches(logicalProject(logicalOneRowRelation()))));
    // with except and replace
    String sql6 = "select * except (v1) replace('new' as v2) from t1";
    PlanChecker.from(MemoTestUtils.createConnectContext()).checkParse(sql6, (checker) -> checker.matches(logicalProject(logicalCheckPolicy(unboundRelation()))));
}

