@Test
public void testSimpleAliasFunction() throws Exception {
    // alias udf should not check java_udf
    Config.enable_java_udf = false;
    createFunction("create global alias function f(int) with parameter(n) as hours_add(now(3), n)");
    createFunction("create alias function f(int) with parameter(n) as hours_sub(now(3), n)");
    String sql = "select f(3)";
    Expression expected = new HoursSub(new Now(new IntegerLiteral(3)), new IntegerLiteral(3));
    PlanChecker.from(connectContext).analyze(sql).matches(logicalOneRowRelation().when(oneRow -> oneRow.getProjects().get(0).child(0).equals(expected)));
    connectContext.setDatabase("test_1");
    Expression expected1 = new HoursAdd(new Now(new IntegerLiteral(3)), new IntegerLiteral(3));
    PlanChecker.from(connectContext).analyze(sql).matches(logicalOneRowRelation().when(oneRow -> oneRow.getProjects().get(0).child(0).equals(expected1)));
    sql = "select test.f(3)";
    Expression expected2 = new HoursSub(new Now(new IntegerLiteral(3)), new IntegerLiteral(3));
    PlanChecker.from(connectContext).analyze(sql).matches(logicalOneRowRelation().when(oneRow -> oneRow.getProjects().get(0).child(0).equals(expected2)));
}

@Test
public void testNestedAliasFunction() throws Exception {
    createFunction("create global alias function f1(int) with parameter(n) as hours_add(now(3), n)");
    createFunction("create global alias function f2(int) with parameter(n) as dayofweek(days_add(f1(3), n))");
    createFunction("create global alias function f3(datev2) with parameter(dt) as hours_sub(days_sub(dt, f2(3)), dayofmonth(f1(f2(4))))");
    Assertions.assertEquals(1, Env.getCurrentEnv().getFunctionRegistry().findUdfBuilder(connectContext.getDatabase(), "f3").size());
    String sql = "select f3(now(3))";
    Expression expected = new HoursSub(new Cast(new DaysSub(new Cast(new Now(new IntegerLiteral(3)), DateV2Type.INSTANCE), new Cast(new DayOfWeek(new DaysAdd(new HoursAdd(new Now(new IntegerLiteral(3)), new IntegerLiteral(3)), new IntegerLiteral(3))), IntegerType.INSTANCE)), DateTimeV2Type.SYSTEM_DEFAULT), new Cast(new DayOfMonth(new HoursAdd(new Now(new IntegerLiteral(3)), new Cast(new DayOfWeek(new DaysAdd(new HoursAdd(new Now(new IntegerLiteral(3)), new IntegerLiteral(3)), new IntegerLiteral(4))), IntegerType.INSTANCE))), IntegerType.INSTANCE));
    PlanChecker.from(connectContext).analyze(sql).matches(logicalOneRowRelation().when(oneRow -> oneRow.getProjects().size() == 1 && oneRow.getProjects().get(0).child(0).equals(expected)));
}

