    DropStatsCommand command5 = new DropStatsCommand(tableNameInfo5, columns, partitionNamesInfo);
    Assertions.assertThrows(AnalysisException.class, () -> command5.validate(connectContext), "Unknown table 'tbl_not_exist'");
