    // test where is not Like and where is not EqualTo
    bc = new ShowBackupCommand("test_db", new LessThan(new UnboundSlot(Lists.newArrayList("snapshotname")), new VarcharLiteral("mysql_edu_mall_mall_source_occupy_1741669209_174166921")));
    Assertions.assertFalse(bc.validate(connectContext));
    // test left key is not snapshotname
    bc = new ShowBackupCommand("test_db", new EqualTo(new UnboundSlot(Lists.newArrayList("notsnapshotname")), new VarcharLiteral("mysql_edu_mall_mall_source_occupy_1741669209_174166921")));
    Assertions.assertFalse(bc.validate(connectContext));
    // test right key is StringLikeLiteral, class is EqualTo
    bc = new ShowBackupCommand("test_db", new EqualTo(new UnboundSlot(Lists.newArrayList("snapshotname")), new StringLiteral("mysql_edu%")));
    Assertions.assertTrue(bc.validate(connectContext));
    // test right key is StringLikeLiteral, class is Like
    bc = new ShowBackupCommand("test_db", new Like(new UnboundSlot(Lists.newArrayList("snapshotname")), new StringLiteral("mysql_edu%")));
    Assertions.assertTrue(bc.validate(connectContext));
    // test right key is StringLikeLiteral but value is empty, class is Like,
    bc = new ShowBackupCommand("test_db", new Like(new UnboundSlot(Lists.newArrayList("snapshotname")), new StringLiteral("")));
    Assertions.assertFalse(bc.validate(connectContext));
}

