@Test
void foreignKeyConstraintTest() throws Exception {
    AddConstraintCommand command = (AddConstraintCommand) new NereidsParser().parseSingle("alter table t1 add constraint fk foreign key (k1) references t2 (k1)");
    try {
        command.run(connectContext, null);
    } catch (Exception e) {
        Assertions.assertEquals("Foreign key constraint requires a primary key constraint [k1] in t2", e.getMessage());
    }
    ((AddConstraintCommand) new NereidsParser().parseSingle("alter table t2 add constraint pk primary key (k1, k2)")).run(connectContext, null);
    ((AddConstraintCommand) new NereidsParser().parseSingle("alter table t1 add constraint fk foreign key (k1, k2) references t2(k1, k2)")).run(connectContext, null);
    PlanChecker.from(connectContext).parse("select * from t1").analyze().matches(logicalOlapScan().when(o -> {
        Constraint c = o.getTable().getConstraint("fk");
        if (c instanceof ForeignKeyConstraint) {
            ForeignKeyConstraint f = (ForeignKeyConstraint) c;
            Column ref1 = f.getReferencedColumn(((SlotReference) o.getOutput().get(0)).getOriginalColumn().get().getName());
            Column ref2 = f.getReferencedColumn(((SlotReference) o.getOutput().get(1)).getOriginalColumn().get().getName());
            return ref1.getName().equals("k1") && ref2.getName().equals("k2");
        }
        return false;
    }));
    PlanChecker.from(connectContext).parse("select * from t2").analyze().matches(logicalOlapScan().when(o -> {
        Constraint c = o.getTable().getConstraint("pk");
        if (c instanceof PrimaryKeyConstraint) {
            Set<String> columnNames = ((PrimaryKeyConstraint) c).getPrimaryKeyNames();
            List<TableIf> foreignTables = ((PrimaryKeyConstraint) c).getForeignTables();
            return columnNames.size() == 2 && columnNames.equals(Sets.newHashSet("k1", "k2")) && foreignTables.size() == 1 && foreignTables.get(0).getName().equals("t1");
        }
        return false;
    }));
    // drop fk
    DropConstraintCommand dropCommand = (DropConstraintCommand) new NereidsParser().parseSingle("alter table t1 drop constraint fk");
    dropCommand.run(connectContext, null);
    PlanChecker.from(connectContext).parse("select * from t1").analyze().matches(logicalOlapScan().when(o -> o.getTable().getConstraintsMapUnsafe().isEmpty()));
    // drop pk and fk referenced it also should be dropped
    ((AddConstraintCommand) new NereidsParser().parseSingle("alter table t1 add constraint fk foreign key (k1, k2) references t2(k1, k2)")).run(connectContext, null);
    ((DropConstraintCommand) new NereidsParser().parseSingle("alter table t2 drop constraint pk")).run(connectContext, null);
    PlanChecker.from(connectContext).parse("select * from t1").analyze().matches(logicalOlapScan().when(o -> o.getTable().getConstraintsMapUnsafe().isEmpty()));
    PlanChecker.from(connectContext).parse("select * from t2").analyze().matches(logicalOlapScan().when(o -> o.getTable().getConstraintsMapUnsafe().isEmpty()));
}

@Test
void cascadeDropTest() throws Exception {
    addConstraint("alter table t1 add constraint pk primary key (k1)");
