@Test
void testAdjustAggNullableWithEmptyGroupBy() {
    SlotReference a = new SlotReference("a", IntegerType.INSTANCE, false);
    SlotReference b = new SlotReference("b", IntegerType.INSTANCE, false);
    LogicalOneRowRelation oneRowRelation = new LogicalOneRowRelation(StatementScopeIdGenerator.newRelationId(), ImmutableList.of(a, b));
    // agg with empty group by
    NamedExpression originOutput1 = new Alias(new Add(new Sum(a), new IntegerLiteral(1)));
    NamedExpression originOutput2 = new Alias(new WindowExpression(new Sum(false, true, new Add(new Sum(b), new IntegerLiteral(1))), ImmutableList.of(a), ImmutableList.of(new OrderExpression(new OrderKey(b, true, true)))));
    Assertions.assertFalse(originOutput1.nullable());
    LogicalAggregate<LogicalOneRowRelation> agg = new LogicalAggregate<>(ImmutableList.of(), ImmutableList.of(originOutput1, originOutput2), oneRowRelation);
    NamedExpression output1 = agg.getOutputs().get(0);
    NamedExpression output2 = agg.getOutputs().get(1);
    Assertions.assertNotEquals(originOutput1, output1);
    Assertions.assertNotEquals(originOutput2, output2);
    Assertions.assertTrue(output1.nullable());
    Expression expectOutput1Child = new Add(new Sum(false, true, a), new IntegerLiteral(1));
    Expression expectOutput2Child = new WindowExpression(new Sum(false, true, new Add(new Sum(false, true, b), new IntegerLiteral(1))), ImmutableList.of(a), ImmutableList.of(new OrderExpression(new OrderKey(b, true, true))));
    Assertions.assertEquals(expectOutput1Child, output1.child(0));
    Assertions.assertEquals(expectOutput2Child, output2.child(0));
}

@Test
void testAdjustAggNullableWithNotEmptyGroupBy() {
    SlotReference a = new SlotReference("a", IntegerType.INSTANCE, false);
    SlotReference b = new SlotReference("b", IntegerType.INSTANCE, false);
    LogicalOneRowRelation oneRowRelation = new LogicalOneRowRelation(StatementScopeIdGenerator.newRelationId(), ImmutableList.of(a, b));
    // agg with not empty group by
    NamedExpression originOutput1 = new Alias(new Add(new Sum(false, true, a), new IntegerLiteral(1)));
    NamedExpression originOutput2 = new Alias(new WindowExpression(new Sum(false, true, new Add(new Sum(false, true, b), new IntegerLiteral(1))), ImmutableList.of(a), ImmutableList.of(new OrderExpression(new OrderKey(b, true, true)))));
    Assertions.assertTrue(originOutput1.nullable());
    LogicalAggregate<LogicalOneRowRelation> agg = new LogicalAggregate<>(ImmutableList.of(new TinyIntLiteral((byte) 1)), ImmutableList.of(originOutput1, originOutput2), oneRowRelation);
    NamedExpression output1 = agg.getOutputs().get(0);
    NamedExpression output2 = agg.getOutputs().get(1);
    Assertions.assertNotEquals(originOutput1, output1);
    Assertions.assertNotEquals(originOutput2, output2);
    Assertions.assertFalse(output1.nullable());
    Expression expectOutput1Child = new Add(new Sum(false, false, a), new IntegerLiteral(1));
    Expression expectOutput2Child = new WindowExpression(new Sum(false, true, new Add(new Sum(false, false, b), new IntegerLiteral(1))), ImmutableList.of(a), ImmutableList.of(new OrderExpression(new OrderKey(b, true, true))));
    Assertions.assertEquals(expectOutput1Child, output1.child(0));
    Assertions.assertEquals(expectOutput2Child, output2.child(0));
}

