@Test
void testLogicalJoin() {
    LogicalOneRowRelation left = new LogicalOneRowRelation(new RelationId(1), ImmutableList.of(new Alias(Literal.of(1L), "a")));
    LogicalOneRowRelation right = new LogicalOneRowRelation(new RelationId(1), ImmutableList.of(new Alias(Literal.of(2L), "b")));
    LogicalJoin<Plan, Plan> actual = new LogicalJoin<>(JoinType.INNER_JOIN, Lists.newArrayList(new EqualTo(new SlotReference(new ExprId(0), "a", BigIntType.INSTANCE, true, Lists.newArrayList()), new SlotReference(new ExprId(1), "b", BigIntType.INSTANCE, true, Lists.newArrayList()))), left, right, null);
    LogicalJoin<Plan, Plan> expected = new LogicalJoin<>(JoinType.INNER_JOIN, Lists.newArrayList(new EqualTo(new SlotReference(new ExprId(0), "a", BigIntType.INSTANCE, true, Lists.newArrayList()), new SlotReference(new ExprId(1), "b", BigIntType.INSTANCE, true, Lists.newArrayList()))), left, right, null);
    Assertions.assertEquals(expected, actual);
    LogicalJoin<Plan, Plan> unexpected = new LogicalJoin<>(JoinType.INNER_JOIN, Lists.newArrayList(new EqualTo(new SlotReference(new ExprId(2), "a", BigIntType.INSTANCE, false, Lists.newArrayList()), new SlotReference(new ExprId(3), "b", BigIntType.INSTANCE, true, Lists.newArrayList()))), left, right, null);
    Assertions.assertNotEquals(unexpected, actual);
}

