@Test
public void testDecimalArithmetic() {
    Multiply multiply = new Multiply(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    Expression expression = TypeCoercionUtils.processBinaryArithmetic(multiply);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(9, 3)));
    Divide divide = new Divide(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    expression = TypeCoercionUtils.processBinaryArithmetic(divide);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(9, 3)));
    Add add = new Add(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    expression = TypeCoercionUtils.processBinaryArithmetic(add);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(10, 3)));
    Subtract sub = new Subtract(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    expression = TypeCoercionUtils.processBinaryArithmetic(sub);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(10, 3)));
}

@Test
public void testProcessInDowngrade() {
    // DecimalV2 slot vs DecimalV3 literal
    InPredicate decimalDowngrade = new InPredicate(new SlotReference("c1", DecimalV2Type.createDecimalV2Type(15, 6)), ImmutableList.of(new DecimalV3Literal(BigDecimal.valueOf(12345.1234567)), new DecimalLiteral(BigDecimal.valueOf(12345.1234))));
    decimalDowngrade = (InPredicate) TypeCoercionUtils.processInPredicate(decimalDowngrade);
    Assertions.assertEquals(DecimalV2Type.createDecimalV2Type(16, 7), decimalDowngrade.getCompareExpr().getDataType());
    // DateV1 slot vs DateV2 literal
    InPredicate dateDowngrade = new InPredicate(new SlotReference("c1", DateType.INSTANCE), ImmutableList.of(new DateLiteral(2024, 4, 12), new DateV2Literal(2024, 4, 12)));
    dateDowngrade = (InPredicate) TypeCoercionUtils.processInPredicate(dateDowngrade);
    Assertions.assertEquals(DateType.INSTANCE, dateDowngrade.getCompareExpr().getDataType());
    // DatetimeV1 slot vs DateLike literal
    InPredicate datetimeDowngrade = new InPredicate(new SlotReference("c1", DateTimeType.INSTANCE), ImmutableList.of(new DateLiteral(2024, 4, 12), new DateV2Literal(2024, 4, 12), new DateTimeLiteral(2024, 4, 12, 18, 25, 30), new DateTimeV2Literal(2024, 4, 12, 18, 25, 30, 0)));
    datetimeDowngrade = (InPredicate) TypeCoercionUtils.processInPredicate(datetimeDowngrade);
    Assertions.assertEquals(DateTimeType.INSTANCE, datetimeDowngrade.getCompareExpr().getDataType());
}

