    List<TNormalizedPlanNode> fourPhaseAggPlans = phaseAgg(4, () -> normalizePlans("select sum(distinct v1), k2 from db1.part1 where dt = '2024-04-10' group by k2"));
    Assertions.assertEquals(fourPhaseAggPlans, threePhaseAggPlans);
}

