@Test
public void testZeroFailureGuarantee() throws InterruptedException {
    String originSql = "select * from t1 where \"k1\" = 1";
    String expectedSql = "select * from t1 where `k1` = 1";
    String[] features = new String[] { "ctas" };
    String targetURLs = "http://127.0.0.1:" + ports.get(0) + "/api/v1/convert," + "http://127.0.0.1:" + ports.get(1) + "/api/v1/convert," + "http://127.0.0.1:" + ports.get(2) + "/api/v1/convert";
    // Reduced for faster testing with production timeouts
    int totalRequests = 30;
    int successCount = 0;
    // Test various failure scenarios while ensuring at least one service is always available
    for (int i = 0; i < totalRequests; i++) {
        if (i < 6) {
            // All servers healthy
            setAllServersHealthy(expectedSql);
        } else if (i < 12) {
            // Server 0 fails, others healthy
            servers.get(0).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 500, \"message\": \"error\"}");
            servers.get(1).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
            servers.get(2).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
        } else if (i < 18) {
            // Servers 0,1 fail, server 2 healthy
            servers.get(0).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 500, \"message\": \"error\"}");
            servers.get(1).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 503, \"message\": \"error\"}");
            servers.get(2).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
        } else if (i < 24) {
            // Only server 1 healthy
            servers.get(0).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 500, \"message\": \"error\"}");
            servers.get(1).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
            servers.get(2).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 500, \"message\": \"error\"}");
        } else {
            // Alternating recovery
            if (i % 2 == 0) {
                servers.get(0).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
                servers.get(1).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 500, \"message\": \"error\"}");
                servers.get(2).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 500, \"message\": \"error\"}");
            } else {
                servers.get(0).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 500, \"message\": \"error\"}");
                servers.get(1).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 500, \"message\": \"error\"}");
                servers.get(2).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
            }
        }
        String result = HttpDialectUtils.convertSql(targetURLs, originSql, "presto", features, "{}");
        if (expectedSql.equals(result)) {
            successCount++;
        }
        // Small delay between requests
        Thread.sleep(50);
    }
    System.out.println("Zero Failure Guarantee Test Results:");
    System.out.println("Total requests: " + totalRequests);
    System.out.println("Successful: " + successCount);
    System.out.println("Success rate: " + (successCount * 100.0 / totalRequests) + "%");
    // Must achieve 100% success rate when at least one service is available
    Assert.assertEquals("Must achieve 100% success rate when service is available", totalRequests, successCount);
}

@Test
public void testNetworkJitterStress() throws InterruptedException {
    String originSql = "select * from t1 where \"k1\" = 1";
    String expectedSql = "select * from t1 where `k1` = 1";
    String[] features = new String[] { "ctas" };
    String targetURLs = "http://127.0.0.1:" + ports.get(0) + "/api/v1/convert," + "http://127.0.0.1:" + ports.get(1) + "/api/v1/convert";
    // Reduced for faster testing with production timeouts
    int totalRequests = 15;
    int successCount = 0;
    // Simulate network jitter while ensuring at least one server is always available
    for (int i = 0; i < totalRequests; i++) {
        double random = Math.random();
        if (random < 0.3) {
            // Server 0 fails, Server 1 works
            servers.get(0).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 500, \"message\": \"timeout\"}");
            servers.get(1).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
        } else if (random < 0.5) {
            // Server 1 fails, Server 0 works
            servers.get(0).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
            servers.get(1).setResponse("{\"version\": \"v1\", \"data\": \"\", \"code\": 503, \"message\": \"service unavailable\"}");
        } else {
            // Both servers work
            servers.get(0).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
            servers.get(1).setResponse("{\"version\": \"v1\", \"data\": \"" + expectedSql + "\", \"code\": 0, \"message\": \"\"}");
        }
        String result = HttpDialectUtils.convertSql(targetURLs, originSql, "presto", features, "{}");
        if (expectedSql.equals(result)) {
            successCount++;
        }
        // Delay between requests for production timeouts
        Thread.sleep(100);
    }
    System.out.println("Network Jitter Test Results:");
    System.out.println("Total requests: " + totalRequests);
    System.out.println("Successful: " + successCount);
    System.out.println("Success rate: " + (successCount * 100.0 / totalRequests) + "%");
    // Must achieve 100% success rate since we ensure at least one server is always available
    Assert.assertEquals("Must handle network jitter with 100% success when service is available", totalRequests, successCount);
}

