    connectContext.getSessionVariable().setEnableNereidsDistributePlanner(false);
    connectContext.getSessionVariable().setDisableJoinReorder(true);
    String sql = "with oooo_oneid as (select identity_value from test.oooo_oneid),\n" + "    aaaa_frm_$oooo as (select j_bbbb,base_id from test.aaaa_target),\n" + "    bbbb_frm_$aaaa_target as (select * from bbbb_target where base_id in (select 1 from aaaa_frm_$oooo)),\n" + "    bbbb_cdn_1602527468_lnkb_bbbb_target$aaaa_target as (select base_id from bbbb_frm_$aaaa_target),\n" + "    bbbb_frm_$oooo as (select *\n" + "                        from bbbb_target\n" + "                        where base_id in (select identity_value from oooo_oneid)\n" + "                      ),\n" + "    cccc_frm_$bbbb_target as (select * from cccc_target where base_id in (select 1 from bbbb_frm_$oooo))\n" + "select\n" + "   j_bbbb in (select base_id from bbbb_cdn_1602527468_lnkb_bbbb_target$aaaa_target),\n" + "   j_bbbb in (select base_id from bbbb_cdn_1602527468_lnkb_bbbb_target$aaaa_target)\n" + "from (select j_bbbb\n" + "     from oooo_oneid\n" + "     left outer join aaaa_frm_$oooo on (oooo_oneid.identity_value = aaaa_frm_$oooo.base_id)\n" + "     left outer join bbbb_frm_$oooo on (oooo_oneid.identity_value = bbbb_frm_$oooo.base_id)\n" + ")final_plain_table";
    StmtExecutor stmtExecutor = new StmtExecutor(connectContext, sql);
    try {
        stmtExecutor.execute();
    } catch (Throwable t) {
        // ignore
    }
    Coordinator coord = stmtExecutor.getCoord();
    Map<PlanFragmentId, FragmentExecParams> fragmentExecParamsMap = coord.getFragmentExecParamsMap();
    for (FragmentExecParams fragmentExecParams : fragmentExecParamsMap.values()) {
        // skip check root fragment
        if (fragmentExecParams.fragment.getChildren().isEmpty()) {
            continue;
        }
        SetMultimap<TNetworkAddress, Integer> receiverIds = LinkedHashMultimap.create();
        ArrayListMultimap<TNetworkAddress, FInstanceExecParam> hostToInstances = ArrayListMultimap.create();
        boolean setRecvrId = false;
        for (FInstanceExecParam instanceExecParam : fragmentExecParams.instanceExecParams) {
            if (instanceExecParam.recvrId != -1) {
                setRecvrId = true;
            }
            receiverIds.put(instanceExecParam.host, instanceExecParam.recvrId);
            hostToInstances.put(instanceExecParam.host, instanceExecParam);
        }
        if (!setRecvrId) {
            // skip check when share broadcast hash table
            continue;
        }
        for (Entry<TNetworkAddress, Collection<Integer>> hostToReceiverIds : receiverIds.asMap().entrySet()) {
            // if this host has 2 instances, it should contain 2 receiverId
            Assertions.assertEquals(hostToInstances.get(hostToReceiverIds.getKey()).size(), hostToReceiverIds.getValue().size());
        }
    }
}

