@Test
public void timeNowTest() throws AnalysisException {
    String curTimeString = FEFunctions.curTime().toSqlImpl(false, false, null, null).replace("'", "");
    String currentTimestampString = FEFunctions.currentTimestamp().toSqlImpl(false, false, null, null).replace("'", "");
    ZonedDateTime zonedDateTime = ZonedDateTime.now(TimeUtils.getTimeZone().toZoneId());
    DateTimeFormatter formatter = null;
    if (Config.enable_date_conversion) {
        formatter = new DateTimeFormatterBuilder().appendPattern("uuuu-MM-dd HH:mm:ss").appendFraction(ChronoField.MICRO_OF_SECOND, 0, 6, true).toFormatter();
    } else {
        formatter = new DateTimeFormatterBuilder().appendPattern("uuuu-MM-dd HH:mm:ss").toFormatter();
    }
    Assert.assertTrue(formatter.format(zonedDateTime).compareTo(currentTimestampString) >= 0);
    String nowTimeString = formatter.format(zonedDateTime).substring(formatter.format(zonedDateTime).indexOf(" ") + 1);
    Assert.assertTrue(nowTimeString.compareTo(curTimeString) >= 0);
}

