public void testLoad() throws Exception {
    new MockUp<StatisticsUtil>() {

        @Mock
        public Column findColumn(long catalogId, long dbId, long tblId, long idxId, String columnName) {
            return new Column("abc", PrimitiveType.BIGINT);
        }

