@Test
public void testSelectBackendIdsForReplicaCreation() throws Exception {
    addBackend(10001, "192.168.1.1", 9050);
    Backend be1 = infoService.getBackend(10001);
    addDisk(be1, "path1", TStorageMedium.HDD, 200 * 1024 * 1024L, 150 * 1024 * 1024L);
    be1.setAlive(true);
    addBackend(10002, "192.168.1.2", 9050);
    Backend be2 = infoService.getBackend(10002);
    addDisk(be2, "path1", TStorageMedium.HDD, 200 * 1024 * 1024L, 150 * 1024 * 1024L);
    be2.setAlive(true);
    addBackend(10003, "192.168.1.3", 9050);
    Backend be3 = infoService.getBackend(10003);
    addDisk(be3, "path1", TStorageMedium.HDD, 200 * 1024 * 1024L, 150 * 1024 * 1024L);
    be3.setAlive(true);
    addBackend(10004, "192.168.1.4", 9050);
    Backend be4 = infoService.getBackend(10004);
    addDisk(be4, "path1", TStorageMedium.HDD, 200 * 1024 * 1024L, 150 * 1024 * 1024L);
    be4.setAlive(true);
    addBackend(10005, "192.168.1.5", 9050);
    Backend be5 = infoService.getBackend(10005);
    addDisk(be5, "path1", TStorageMedium.HDD, 200 * 1024 * 1024L, 150 * 1024 * 1024L);
    be5.setAlive(true);
    // no effect with compute node
    addBackend(10006, "192.168.1.6", 9050);
    Backend be6 = infoService.getBackend(10006);
    addDisk(be6, "path1", TStorageMedium.HDD, 200 * 1024 * 1024L, 150 * 1024 * 1024L);
    be6.setAlive(true);
    setComputeNode(be6, Tag.DEFAULT_BACKEND_TAG);
    ReplicaAllocation replicaAlloc = ReplicaAllocation.DEFAULT_ALLOCATION;
    // also check if the random selection logic can evenly distribute the replica.
    Map<Long, Integer> beCounterMap = Maps.newHashMap();
    for (int i = 0; i < 30000; ++i) {
        Pair<Map<Tag, List<Long>>, TStorageMedium> ret = infoService.selectBackendIdsForReplicaCreation(replicaAlloc, Maps.newHashMap(), TStorageMedium.HDD, false, false);
        Map<Tag, List<Long>> res = ret.first;
        Assert.assertEquals(3, res.get(Tag.DEFAULT_BACKEND_TAG).size());
        for (Long beId : res.get(Tag.DEFAULT_BACKEND_TAG)) {
            beCounterMap.put(beId, beCounterMap.getOrDefault(beId, 0) + 1);
        }
    }
    Set<Long> expectBackendIds = infoService.getMixBackends().stream().filter(Backend::isAlive).map(Backend::getId).collect(Collectors.toSet());
    Assert.assertEquals(expectBackendIds, beCounterMap.keySet().stream().collect(Collectors.toSet()));
    List<Integer> list = Lists.newArrayList(beCounterMap.values());
    Collections.sort(list);
    int max = list.get(list.size() - 1);
    int diff = max - list.get(0);
    // The max replica num and min replica num's diff is less than 30%.
    Assert.assertTrue((diff * 1.0 / max) < 0.3);
}

@Test
public void testCsvSchemaParse() {
    Config.enable_date_conversion = true;
    Map<String, String> properties = Maps.newHashMap();
    properties.put(FileFormatConstants.PROP_CSV_SCHEMA, "k1:int;k2:bigint;k3:float;k4:double;k5:smallint;k6:tinyint;k7:bool;" + "k8:char(10);k9:varchar(20);k10:date;k11:datetime;k12:decimal(10,2)");
    List<Column> csvSchema = Lists.newArrayList();
    try {
        FileFormatUtils.parseCsvSchema(csvSchema, properties.get(FileFormatConstants.PROP_CSV_SCHEMA));
        Assert.fail();
    } catch (AnalysisException e) {
        e.printStackTrace();
        Assert.assertTrue(e.getMessage().contains("unsupported column type: bool"));
    }
    csvSchema.clear();
    properties.put(FileFormatConstants.PROP_CSV_SCHEMA, "k1:int;k2:bigint;k3:float;k4:double;k5:smallint;k6:tinyint;k7:boolean;" + "k8:string;k9:date;k10:datetime;k11:decimal(10, 2);k12:decimal( 38,10); k13:datetime(5)");
    try {
        FileFormatUtils.parseCsvSchema(csvSchema, properties.get(FileFormatConstants.PROP_CSV_SCHEMA));
        Assert.assertEquals(13, csvSchema.size());
        Column decimalCol = csvSchema.get(10);
        Assert.assertEquals(10, decimalCol.getPrecision());
        Assert.assertEquals(2, decimalCol.getScale());
        decimalCol = csvSchema.get(11);
        Assert.assertEquals(38, decimalCol.getPrecision());
        Assert.assertEquals(10, decimalCol.getScale());
        Column datetimeCol = csvSchema.get(12);
        Assert.assertEquals(5, datetimeCol.getScale());
        for (int i = 0; i < csvSchema.size(); i++) {
            Column col = csvSchema.get(i);
            switch(col.getName()) {
                case "k1":
                    Assert.assertEquals(PrimitiveType.INT, col.getType().getPrimitiveType());
                    break;
                case "k2":
                    Assert.assertEquals(PrimitiveType.BIGINT, col.getType().getPrimitiveType());
                    break;
                case "k3":
                    Assert.assertEquals(PrimitiveType.FLOAT, col.getType().getPrimitiveType());
                    break;
                case "k4":
                    Assert.assertEquals(PrimitiveType.DOUBLE, col.getType().getPrimitiveType());
                    break;
                case "k5":
                    Assert.assertEquals(PrimitiveType.SMALLINT, col.getType().getPrimitiveType());
                    break;
                case "k6":
                    Assert.assertEquals(PrimitiveType.TINYINT, col.getType().getPrimitiveType());
                    break;
                case "k7":
                    Assert.assertEquals(PrimitiveType.BOOLEAN, col.getType().getPrimitiveType());
                    break;
                case "k8":
                    Assert.assertEquals(PrimitiveType.STRING, col.getType().getPrimitiveType());
                    break;
                case "k9":
                    Assert.assertEquals(PrimitiveType.DATEV2, col.getType().getPrimitiveType());
                    break;
                case "k10":
                    Assert.assertEquals(PrimitiveType.DATETIMEV2, col.getType().getPrimitiveType());
                    break;
                case "k11":
                    Assert.assertEquals(PrimitiveType.DECIMAL64, col.getType().getPrimitiveType());
                    break;
                case "k12":
                    Assert.assertEquals(PrimitiveType.DECIMAL128, col.getType().getPrimitiveType());
                    break;
                case "k13":
                    Assert.assertEquals(PrimitiveType.DATETIMEV2, col.getType().getPrimitiveType());
                    break;
                default:
                    Assert.fail("unknown column name: " + col.getName());
            }
        }
    } catch (AnalysisException e) {
        e.printStackTrace();
        Assert.fail();
    }
}

