@Test
public void testFinishTransaction() throws UserException {
    long transactionId = masterTransMgr.beginTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(CatalogTestUtil.testTableId1), CatalogTestUtil.testTxnLabel1, transactionSource, LoadJobSourceType.FRONTEND, Config.stream_load_default_timeout_second);
    // commit a transaction
    List<TabletCommitInfo> transTablets = generateTabletCommitInfos(CatalogTestUtil.testTabletId1, allBackends);
    OlapTable testTable1 = (OlapTable) (masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId1));
    masterTransMgr.commitTransactionWithoutLock(CatalogTestUtil.testDbId1, Lists.newArrayList(testTable1), transactionId, transTablets, null);
    TransactionState transactionState = fakeEditLog.getTransaction(transactionId);
    Assert.assertEquals(TransactionStatus.COMMITTED, transactionState.getTransactionStatus());
    checkTableVersion(testTable1, 1, 2);
    slaveTransMgr.replayUpsertTransactionState(transactionState);
    // finish transaction
    Map<String, Map<Long, Long>> keyToSuccessTablets = new HashMap<>();
    DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, Lists.newArrayList(CatalogTestUtil.testBackendId2, CatalogTestUtil.testBackendId3), transactionState.getTransactionId(), CatalogTestUtil.testTabletId1, 14);
    DatabaseTransactionMgrTest.setTransactionFinishPublish(transactionState, allBackends, keyToSuccessTablets);
    Map<Long, Long> partitionVisibleVersions = Maps.newHashMap();
    Map<Long, Set<Long>> backendPartitions = Maps.newHashMap();
    masterTransMgr.finishTransaction(CatalogTestUtil.testDbId1, transactionId, partitionVisibleVersions, backendPartitions);
    transactionState = fakeEditLog.getTransaction(transactionId);
    Assert.assertEquals(TransactionStatus.VISIBLE, transactionState.getTransactionStatus());
    // check partition version
    Partition testPartition = masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId1).getPartition(CatalogTestUtil.testPartition1);
    Assert.assertEquals(CatalogTestUtil.testStartVersion + 1, testPartition.getVisibleVersion());
    Assert.assertEquals(CatalogTestUtil.testStartVersion + 2, testPartition.getNextVersion());
    // check replica version
    Tablet tablet = testPartition.getIndex(CatalogTestUtil.testIndexId1).getTablet(CatalogTestUtil.testTabletId1);
    for (Replica replica : tablet.getReplicas()) {
        if (replica.getId() == CatalogTestUtil.testReplicaId1) {
            Assert.assertEquals(CatalogTestUtil.testStartVersion, replica.getVersion());
        } else {
            Assert.assertEquals(CatalogTestUtil.testStartVersion + 1, replica.getVersion());
        }
    }
    Assert.assertEquals(ImmutableMap.of(testPartition.getId(), CatalogTestUtil.testStartVersion + 1), partitionVisibleVersions);
    Set<Long> partitionIds = Sets.newHashSet(testPartition.getId());
    Assert.assertEquals(partitionIds, backendPartitions.get(CatalogTestUtil.testBackendId1));
    Assert.assertEquals(partitionIds, backendPartitions.get(CatalogTestUtil.testBackendId2));
    Assert.assertEquals(partitionIds, backendPartitions.get(CatalogTestUtil.testBackendId3));
    checkTableVersion(testTable1, 2, 3);
    // slave replay new state and compare catalog
    slaveTransMgr.replayUpsertTransactionState(transactionState);
    Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
}

@Test
public void testFinishTransactionWithOneFailed() throws UserException {
    Table testTable1 = masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId1);
    Partition testPartition = testTable1.getPartition(CatalogTestUtil.testPartition1);
    Tablet tablet = testPartition.getIndex(CatalogTestUtil.testIndexId1).getTablet(CatalogTestUtil.testTabletId1);
    Replica replica1 = tablet.getReplicaById(CatalogTestUtil.testReplicaId1);
    Replica replica2 = tablet.getReplicaById(CatalogTestUtil.testReplicaId2);
    Replica replica3 = tablet.getReplicaById(CatalogTestUtil.testReplicaId3);
    Map<Long, Long> partitionVisibleVersions = Maps.newHashMap();
    Map<Long, Set<Long>> backendPartitions = Maps.newHashMap();
    // commit a transaction with 1,2 success
    if (true) {
        FakeEnv.setEnv(masterEnv);
        long transactionId = masterTransMgr.beginTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(CatalogTestUtil.testTableId1), CatalogTestUtil.testTxnLabel1, transactionSource, LoadJobSourceType.FRONTEND, Config.stream_load_default_timeout_second);
        List<TabletCommitInfo> transTablets = generateTabletCommitInfos(CatalogTestUtil.testTabletId1, Lists.newArrayList(CatalogTestUtil.testBackendId1, CatalogTestUtil.testBackendId2));
        masterTransMgr.commitTransactionWithoutLock(CatalogTestUtil.testDbId1, Lists.newArrayList(testTable1), transactionId, transTablets, null);
        // follower catalog replay the transaction
        TransactionState transactionState = fakeEditLog.getTransaction(transactionId);
        FakeEnv.setEnv(slaveEnv);
        slaveTransMgr.replayUpsertTransactionState(transactionState);
        Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
        // master finish the transaction failed
        FakeEnv.setEnv(masterEnv);
        Map<String, Map<Long, Long>> keyToSuccessTablets = new HashMap<>();
        // backend2 publish failed
        DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, Lists.newArrayList(CatalogTestUtil.testBackendId1), transactionState.getTransactionId(), CatalogTestUtil.testTabletId1, 14);
        DatabaseTransactionMgrTest.setTransactionFinishPublish(transactionState, Lists.newArrayList(CatalogTestUtil.testBackendId1, CatalogTestUtil.testBackendId2), keyToSuccessTablets);
        masterTransMgr.finishTransaction(CatalogTestUtil.testDbId1, transactionId, partitionVisibleVersions, backendPartitions);
        Assert.assertEquals(TransactionStatus.COMMITTED, transactionState.getTransactionStatus());
        Assert.assertTrue(partitionVisibleVersions.isEmpty());
        Assert.assertTrue(backendPartitions.isEmpty());
        // because after calling `finishTransaction`, the txn state is COMMITTED, not VISIBLE,
        // so all replicas' version are not changed.
        checkReplicaVersion(replica1, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, -1);
        checkReplicaVersion(replica2, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, -1);
        checkReplicaVersion(replica3, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1);
        // backend2 publish success
        Map<Long, Long> backend2SuccTablets = Maps.newHashMap();
        backend2SuccTablets.put(CatalogTestUtil.testTabletId1, 14L);
        transactionState.getPublishVersionTasks().get(CatalogTestUtil.testBackendId2).get(0).setSuccTablets(backend2SuccTablets);
        masterTransMgr.finishTransaction(CatalogTestUtil.testDbId1, transactionId, partitionVisibleVersions, backendPartitions);
        Assert.assertEquals(TransactionStatus.VISIBLE, transactionState.getTransactionStatus());
        checkReplicaVersion(replica1, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion + 1, -1);
        checkReplicaVersion(replica2, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion + 1, -1);
        checkReplicaVersion(replica3, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1);
        // follower catalog replay the transaction
        transactionState = fakeEditLog.getTransaction(transactionId);
        FakeEnv.setEnv(slaveEnv);
        slaveTransMgr.replayUpsertTransactionState(transactionState);
        Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
    }
    // commit another transaction with 1,3 success
    long transactionId2;
    if (true) {
        FakeEnv.setEnv(masterEnv);
        transactionId2 = masterTransMgr.beginTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(CatalogTestUtil.testTableId1), CatalogTestUtil.testTxnLabel2, transactionSource, LoadJobSourceType.FRONTEND, Config.stream_load_default_timeout_second);
        List<TabletCommitInfo> transTablets = generateTabletCommitInfos(CatalogTestUtil.testTabletId1, Lists.newArrayList(CatalogTestUtil.testBackendId1, CatalogTestUtil.testBackendId3));
        try {
            masterTransMgr.commitTransactionWithoutLock(CatalogTestUtil.testDbId1, Lists.newArrayList(testTable1), transactionId2, transTablets, null);
            Assert.fail();
        } catch (TabletQuorumFailedException e) {
            TransactionState transactionState = masterTransMgr.getTransactionState(CatalogTestUtil.testDbId1, transactionId2);
            // check status is prepare, because the commit failed
            Assert.assertEquals(TransactionStatus.PREPARE, transactionState.getTransactionStatus());
        }
    }
    // commit the second transaction with 1,2,3 success
    if (true) {
        List<TabletCommitInfo> transTablets = generateTabletCommitInfos(CatalogTestUtil.testTabletId1, allBackends);
        masterTransMgr.commitTransactionWithoutLock(CatalogTestUtil.testDbId1, Lists.newArrayList(testTable1), transactionId2, transTablets, null);
        TransactionState transactionState = fakeEditLog.getTransaction(transactionId2);
        // check status is commit
        Assert.assertEquals(TransactionStatus.COMMITTED, transactionState.getTransactionStatus());
        // check partition version
        checkPartitionVersion(testPartition, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion + 3);
        // follower catalog replay the transaction
        transactionState = fakeEditLog.getTransaction(transactionId2);
        FakeEnv.setEnv(slaveEnv);
        slaveTransMgr.replayUpsertTransactionState(transactionState);
        Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
        // master finish the transaction2
        Map<String, Map<Long, Long>> keyToSuccessTablets = new HashMap<>();
        // backend2 publish failed
        DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, allBackends, transactionState.getTransactionId(), CatalogTestUtil.testTabletId1, CatalogTestUtil.testStartVersion + 3);
        DatabaseTransactionMgrTest.setTransactionFinishPublish(transactionState, allBackends, keyToSuccessTablets);
        masterTransMgr.finishTransaction(CatalogTestUtil.testDbId1, transactionId2, partitionVisibleVersions, backendPartitions);
        Assert.assertEquals(TransactionStatus.VISIBLE, transactionState.getTransactionStatus());
        checkReplicaVersion(replica1, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion + 2, -1);
        checkReplicaVersion(replica2, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion + 2, -1);
        checkReplicaVersion(replica3, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion + 1);
        // check partition version
        checkPartitionVersion(testPartition, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion + 3);
        transactionState = fakeEditLog.getTransaction(transactionId2);
        FakeEnv.setEnv(slaveEnv);
        slaveTransMgr.replayUpsertTransactionState(transactionState);
        Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
    }
}

