        List<SubTransactionInfo> subTransactionInfos = Lists.newArrayList(new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, allBackends), new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, allBackends), new SubTransactionInfo(table2, CatalogTestUtil.testTabletId2, allBackends), new SubTransactionInfo(table2, CatalogTestUtil.testTabletId2, allBackends));
