        transactionState.setSubTxnIds(subTransactionStates.stream().map(SubTransactionState::getSubTransactionId).collect(Collectors.toList()));
        masterTransMgr.commitTransactionWithoutLock(CatalogTestUtil.testDbId1, Lists.newArrayList(table1, table2), transactionId, subTransactionStates, 300000);
        Assert.assertEquals(TransactionStatus.COMMITTED, transactionState.getTransactionStatus());
        // check partition version
        checkVersion(table1, CatalogTestUtil.testPartition1, CatalogTestUtil.testIndexId1, CatalogTestUtil.testTabletId1, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 5, CatalogTestUtil.testStartVersion);
        checkVersion(table2, CatalogTestUtil.testPartition2, CatalogTestUtil.testIndexId2, CatalogTestUtil.testTabletId2, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 4, CatalogTestUtil.testStartVersion);
        // check table1 replica last success and failed version: last success version not change,
        // because not published
        if (true) {
            checkReplicaVersion(CatalogTestUtil.testDbId1, CatalogTestUtil.testTableId1, CatalogTestUtil.testPartition1, CatalogTestUtil.testIndexId1, CatalogTestUtil.testTabletId1, CatalogTestUtil.testReplicaId1, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, -1);
            checkReplicaVersion(CatalogTestUtil.testDbId1, CatalogTestUtil.testTableId1, CatalogTestUtil.testPartition1, CatalogTestUtil.testIndexId1, CatalogTestUtil.testTabletId1, CatalogTestUtil.testReplicaId2, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, -1);
            checkReplicaVersion(replica13, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1);
        }
        // check table2 replica last success and failed version
        if (true) {
            Partition testPartition = masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId2).getPartition(CatalogTestUtil.testPartition2);
            Tablet tablet = testPartition.getIndex(CatalogTestUtil.testIndexId2).getTablet(CatalogTestUtil.testTabletId2);
            for (Replica replica : tablet.getReplicas()) {
                Assert.assertEquals(-1, replica.getLastFailedVersion());
                Assert.assertEquals(CatalogTestUtil.testStartVersion, replica.getLastSuccessVersion());
            }
        }
        transactionState = fakeEditLog.getTransaction(transactionId);
        FakeEnv.setEnv(slaveEnv);
        slaveTransMgr.replayUpsertTransactionState(transactionState);
        Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
    }
}

