    checkVersion(table1, CatalogTestUtil.testPartition1, CatalogTestUtil.testIndexId1, CatalogTestUtil.testTabletId1, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion);
    checkVersion(table2, CatalogTestUtil.testPartition2, CatalogTestUtil.testIndexId2, CatalogTestUtil.testTabletId2, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion);
    // begin txn
    long transactionId = masterTransMgr.beginTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(CatalogTestUtil.testTableId1), CatalogTestUtil.testTxnLabel1, transactionSource, LoadJobSourceType.FRONTEND, Config.stream_load_default_timeout_second);
    TransactionState transactionState = fakeEditLog.getTransaction(transactionId);
    // commit table1, table2, table1
    List<SubTransactionInfo> subTransactionInfos = Lists.newArrayList(new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, allBackends), new SubTransactionInfo(table2, CatalogTestUtil.testTabletId2, allBackends), new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, allBackends));
    List<SubTransactionState> subTransactionStates = generateSubTransactionStates(transactionState, subTransactionInfos);
    // commit txn
    transactionState.setSubTxnIds(subTransactionStates.stream().map(SubTransactionState::getSubTransactionId).collect(Collectors.toList()));
    masterTransMgr.commitTransactionWithoutLock(CatalogTestUtil.testDbId1, Lists.newArrayList(table1, table2), transactionId, subTransactionStates, 300000);
    // check status is committed
    Assert.assertEquals(TransactionStatus.COMMITTED, transactionState.getTransactionStatus());
    // check partition version
    checkVersion(table1, CatalogTestUtil.testPartition1, CatalogTestUtil.testIndexId1, CatalogTestUtil.testTabletId1, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 3, CatalogTestUtil.testStartVersion);
    checkVersion(table2, CatalogTestUtil.testPartition2, CatalogTestUtil.testIndexId2, CatalogTestUtil.testTabletId2, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion);
    // slave replay new state and compare catalog
    FakeEnv.setEnv(slaveEnv);
    slaveTransMgr.replayUpsertTransactionState(transactionState);
    Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
    checkTableVersion(table1, 1, 2);
    checkTableVersion(table2, 1, 2);
    // finish transaction
    Map<String, Map<Long, Long>> keyToSuccessTablets = new HashMap<>();
    DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, allBackends, subTransactionStates.get(0).getSubTransactionId(), CatalogTestUtil.testTabletId1, 14);
    DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, allBackends, subTransactionStates.get(1).getSubTransactionId(), CatalogTestUtil.testTabletId2, 13);
    DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, Lists.newArrayList(CatalogTestUtil.testBackendId2, CatalogTestUtil.testBackendId3), subTransactionStates.get(2).getSubTransactionId(), CatalogTestUtil.testTabletId1, 15);
    DatabaseTransactionMgrTest.setTransactionFinishPublish(transactionState, allBackends, keyToSuccessTablets);
    Map<Long, Long> partitionVisibleVersions = Maps.newHashMap();
    Map<Long, Set<Long>> backendPartitions = Maps.newHashMap();
    masterTransMgr.finishTransaction(CatalogTestUtil.testDbId1, transactionId, partitionVisibleVersions, backendPartitions);
    Assert.assertEquals(TransactionStatus.VISIBLE, transactionState.getTransactionStatus());
    // check table1 partition version
    Partition testPartition = masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId1).getPartition(CatalogTestUtil.testPartition1);
    Assert.assertEquals(CatalogTestUtil.testStartVersion + 2, testPartition.getVisibleVersion());
    Assert.assertEquals(CatalogTestUtil.testStartVersion + 3, testPartition.getNextVersion());
    // check table1 replica version, table1 has 3 replicas
    Tablet tablet = testPartition.getIndex(CatalogTestUtil.testIndexId1).getTablet(CatalogTestUtil.testTabletId1);
    for (Replica replica : tablet.getReplicas()) {
        if (replica.getId() == CatalogTestUtil.testReplicaId1) {
            // TODO replica version is [CatalogTestUtil.testStartVersion + 1] is an improvement
            Assert.assertEquals(CatalogTestUtil.testStartVersion, replica.getVersion());
        } else {
            Assert.assertEquals(CatalogTestUtil.testStartVersion + 2, replica.getVersion());
        }
    }
    // check table2 version, table2 has 1 replicas
    checkVersion(table2, CatalogTestUtil.testPartition2, CatalogTestUtil.testIndexId2, CatalogTestUtil.testTabletId2, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion + 1);
    checkTableVersion(table1, 2, 3);
    checkTableVersion(table2, 2, 3);
    // slave replay new state and compare catalog
    slaveTransMgr.replayUpsertTransactionState(transactionState);
    Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
}

